window.JASTROW_CHUNKS[1029]={"44112":{"h":"פּוֹתַחַת","r":"KRU15191","alt":[],"source":"krupnik","glosses":[{"text":"lock","label":""}],"html":"<p>מנעול lock  ב״ב פ״ו מ״ה: מי שיש לו בור וכו׳ עושה לו פותחת.</p>","notation":["נ׳"]},"44113":{"h":"פּוּתִי","r":"KRU15192","alt":["פּוּתְיָא","פּוּתְיָה"],"source":"krupnik","glosses":[{"text":"width","label":""}],"html":"<p>רוחב width  תוס׳ צוק׳ אהל׳ י׳ א׳: פותי טפח; תרג׳ דהי״ב ג׳ ד׳ (רוחב הבית): פותיא דביתא; יב׳ ס״ג ע״ב: לפותיה.</p>","notation":[]},"44114":{"h":"פּוּתְנַק","r":"KRU15193","alt":[],"source":"krupnik","glosses":[{"text":"pennyroyal","label":""}],"html":"<p>מין צמח pennyroyal  שבת ק״ט ע״ב: יועזר – פּותנק.</p>","notation":["ז׳"]},"44115":{"h":"פּוּתְתָא","r":"KRU15194","alt":[],"source":"krupnik","glosses":[{"text":"bread","label":""}],"html":"<p>פת לחם bread  ירוש׳ ע״ז פ״ב מ״א ע״א: פותתא וכו׳ תבשילא וכו׳.</p>","notation":["ז׳"]},"44116":{"h":"פַּזּוּמְקֵי","r":"KRU15195","alt":[],"source":"krupnik","glosses":[{"text":"shoes","label":""}],"html":"<p>נעלים shoes  ילק׳ עמ׳ תקמ״ב: מנקט פזומקי.</p>","notation":["ז״ר"]},"44117":{"h":"פָּזַז","r":"KRU15196","alt":[],"source":"krupnik","glosses":[{"text":"to sound","label":"1"},{"text":"to be rash","label":"2"}],"html":"<p>1 צלצל to sound  במ״ר פ״ד: קולו פוזז.\n2 נחפז ביותר to be rash  שבת נ״ה ע״ב: פחז כמים – פזתה וכו׳.</p>","notation":["פ״ע"]},"44118":{"h":"פַּזִּי","r":"KRU15197","alt":[],"source":"krupnik","glosses":[{"text":"a man’s name","label":""}],"html":"<p>a man’s name  ירוש׳ מגי׳ פ״ד ע״ה ע״א: חנניה בן פזי. </p>","notation":["שם איש"]},"44119":{"h":"פְּזִיזָא","r":"KRU15198","alt":[],"source":"krupnik","glosses":[{"text":"rash, overhasty","label":""}],"html":"<p>נחפז rash, overhasty  כת׳ קי״ב ע״א: עמא פזיזא דקדמיתו פומייכו לאודניכו.</p>","notation":["ז׳"]},"44120":{"h":"פָּזִיחַ","r":"KRU15199","alt":["פָּזִיק"],"source":"krupnik","glosses":[{"text":"substitutes for nazir","label":""}],"html":"<p>כנוי לנזיר substitutes for nazir  נזיר פ״א מ״א: כל כנויי נזירות כנזירות וכו׳ פזיח וכו׳; ירוש׳ שם נ״א ע״א: פזיק.</p>","notation":[]},"44121":{"h":"פָּזַל","r":"KRU15200","alt":[],"source":"krupnik","glosses":[{"text":"to turn one’s head","label":""}],"html":"<p>הפך פניו to turn one’s head  פסיק״ר פי״ד: פוזלת ומסתכלת בעול.</p>","notation":["פ״י"]},"44122":{"h":"פַּזֵּם","r":"KRU15201","alt":[],"source":"krupnik","glosses":[{"text":"to reply","label":"פַעל,"}],"html":"<p>פַעל, השיב, ענה to reply  תרג׳ איוב ג׳ ב׳ (ויען איוב): ופזים איוב.</p>","notation":[]},"44123":{"h":"פַּזְמְקֵי","r":"KRU15203","alt":[],"source":"krupnik","glosses":[{"text":"shoes","label":""}],"html":"<p>נעלים shoes  שבת ס״ב ע״א: מגפיים – פזמקי.</p>","notation":["ז״ר"]},"44124":{"h":"פָּזַר","r":"KRU15204","alt":[],"source":"krupnik","glosses":[{"text":"to be scattered","label":"נִתְפַּזֵּר הפ׳,"}],"html":"<p>נִתְפַּזֵּר הפ׳, נפרד ונפוץ to be scattered  שבת ט״ז ע״ב: נגע׳ פ״ד מ״ג: מכונסת ונתפזרה.</p>","notation":["Marked biblical in source"]},"44125":{"h":"פִּזְרָא","r":"KRU15205","alt":[],"source":"krupnik","glosses":[{"text":"stick","label":""}],"html":"<p>מקל stick  ב״ק כ״ח ע״א: לנקוט פזרא וליתיב.</p>","notation":["ז׳"]},"44126":{"h":"פַּח","r":"KRU15206","alt":[],"source":"krupnik","glosses":[{"text":"disappointment","label":""}],"html":"<p>פַּחֵי נֶפֶשׁ תוחלת נכזבה disappointment  ר״ה פ״ב מ״ו: שואלין אותם ראשי דברים לא שהיו צריכין להן אלא כדי שלא יצאו בפחי נפש בשביל שיהו רגילים לבא.</p>","notation":["Marked biblical in source"]},"44127":{"h":"פָּחַד","r":"KRU15207","alt":[],"source":"krupnik","glosses":[{"text":"to be frightened","label":"נִפְחַד נפ׳,"},{"text":"to be afraid","label":"הִתְפַּחֵד התפ׳,"}],"html":"<p>נִפְחַד נפ׳, ·– נבהל to be frightened  אסת״ר ד׳ ט״ו: היתה אסתר נפחדת מאד.\nהִתְפַּחֵד התפ׳, התיירא to be afraid  דב״ר פ״א: מתייראין ומתפחדין מכם.</p>","notation":[]},"44128":{"h":"פָּחוֹרָה","r":"KRU15208","alt":[],"source":"krupnik","glosses":[{"text":"a man’s name","label":""}],"html":"<p>a man’s name  ירוש׳ מעש״ש פ״ה נ״ו ע״ד: אלעזר בן פחורה. </p>","notation":["שם איש"]},"44129":{"h":"פָּחוּת","r":"KRU15209","alt":[],"source":"krupnik","glosses":[{"text":"less","label":"1"},{"text":"inferior","label":"2"}],"html":"<p>1 מעט מן less  פס׳ מ״ז ע״א: לא פחות ולא יותר.\n2 גרוע, ירוד inferior  תנח׳ תרומה ז׳: נחשת וכו׳ שהיא פחותה שבכולם.</p>","notation":["ת׳"]},"44130":{"h":"פָּחוֹת","r":"KRU15210","alt":[],"source":"krupnik","glosses":[{"text":"chisel","label":""}],"html":"<p>מין כלי לפיסול chisel  תוס׳ צוק׳ כל׳ ב״ב ז׳ ג׳: יד הפחות ובן הפחות.</p>","notation":["ז׳"]},"44131":{"h":"פְּחוּתָא","r":"KRU15211","alt":[],"source":"krupnik","glosses":[{"text":"rubbish","label":""}],"html":"<p>פחת, פסולת rubbish  פסיק׳ עשר צ״ה ע״ב: מן פחותיה דביתך.</p>","notation":["ז׳"]},"44132":{"h":"פַּחֲזִיתָא","r":"KRU15212","alt":[],"source":"krupnik","glosses":[{"text":"rashness","label":""}],"html":"<p>פזיזות ומהירות rashness  כת׳ קי״ב ע״א: עמא פזיזא דקדמיתו פומייכו לאודנייכו אכתי בפחזיתייכו קיימיתו.</p>","notation":["נ׳"]},"44133":{"h":"פְּחָח","r":"KRU15213","alt":[],"source":"krupnik","glosses":[{"text":"poorly dressed","label":""}],"html":"<p>קרוע ובלוי poorly dressed  תרג׳ יש׳ כ׳ ג׳ (ערום ויחף): פחח ויחיף.</p>","notation":["ת׳"]},"44134":{"h":"פַּחְיָא","r":"KRU15215","alt":[],"source":"krupnik","glosses":[{"text":"cackling hen","label":""}],"html":"<p>תרנגולת פועה cackling hen  ביצה ו׳ ע״ב—ז׳ ע״א: ביעי דפחיא וכו׳ ביעי דשחוטה.</p>","notation":["נ׳"]},"44135":{"h":"פָּחִים","r":"KRU15216","alt":[],"source":"krupnik","glosses":[{"text":"equal","label":""}],"html":"<p>שוה equal  תרג׳ מש׳ ג׳ ט״ו (וכל חפציך לא ישוו בה): וכל מדעם לא פחים לה.</p>","notation":["ת׳"]},"44136":{"h":"פְּחֵית","r":"KRU15218","alt":[],"source":"krupnik","glosses":[{"text":"pit","label":""}],"html":"<p>בור, פחת pit  תרג׳ יר׳ י״ח כ׳ (כרו שוחה לנפשי): כרו פחית למקטלי.</p>","notation":["נ׳"]},"44137":{"h":"פְּחִיתָה","r":"KRU15219","alt":[],"source":"krupnik","glosses":[{"text":"carving","label":""}],"html":"<p>עשית גומא carving  ביצה ל״ב ע״א: פחיתת נר.</p>","notation":["נ׳"]},"44138":{"h":"פְּחָל","r":"KRU15220","alt":[],"source":"krupnik","glosses":[{"text":"name of a place","label":""}],"html":"<p>name of a place  ירוש׳ שבי׳ פ״ו ל״ו ע״ג: ר׳ זעירא אזל לחמתא דפחל. </p>","notation":["שם מקום"]},"44139":{"h":"פַּחֲלָא","r":"KRU15221","alt":["פחלץ"],"source":"krupnik","glosses":[{"text":"mat","label":""}],"html":"<p>מחצלת mat  ירוש׳ שבוע׳ פ״ג ל״ד ע״ד: פחלין דגמלין; נד׳ פ״ג ל״ז ע״ד: פחלץ של גמלין.</p>","notation":[]},"44140":{"h":"פהם","r":"KRU15222","alt":[],"source":"krupnik","glosses":[{"text":"to become black","label":"נִפְחַם נפ׳,"}],"html":"<p>נִפְחַם נפ׳, נעשה שחור to become black  ילק׳ שה״ש תתקפ״ב: נפחם בשמש.</p>","notation":["Source marks no qal form"]},"44141":{"h":"פִּחֵם","r":"KRU15223","alt":[],"source":"krupnik","glosses":[{"text":"to blacken","label":"פיעל,"}],"html":"<p>פיעל, השחיר to blacken  תוס׳ מעש״ש ח׳ י״ג: בית ע״ז מפחמין אותו בפיחמין.\nנִתְפַּחֵם נתפ׳, עי׳ נִפְחַם. ב״ר פי״ח: נתפחמו פני הנשים מפני השמש. </p>","notation":[]},"44142":{"h":"פֶּחָמִי","r":"KRU15224","alt":[],"source":"krupnik","glosses":[{"text":"smith","label":""}],"html":"<p>נפח smith  בר׳ כ״ח ע״א: מכותלי ביתך אתה ניכר שפחמי אתה.</p>","notation":["ז׳"]},"44143":{"h":"פָּחַס","r":"KRU15225","alt":[],"source":"krupnik","glosses":[{"text":"to smash","label":"1"},{"text":"to stir up","label":"2"}],"html":"<p>1 מיעך ולחץ to smash  ע״ז פ״ד מ״ה: כיצד מבטלה וכו׳ פחסה אעפ״י שלא חיסרה בטלה.\n2 שכשך את הנוזלים to stir up  שם ע״ב ע״ב: פחסתו צלוחיתו.</p>","notation":["פ״י"]},"44144":{"h":"פְּחַר","r":"KRU15226","alt":["פַּחֲרָא"],"source":"krupnik","glosses":[{"text":"clay","label":"1"},{"text":"fragment","label":"2"}],"html":"<p>1 חרס clay  תרג׳ יב״ע שמ׳ י״ב כ״ב: מן פחרא.\n2 שבר כלי חרס, חרש fragment  תרג׳ איוב ב׳ ח׳ (ויקח לו חרש): ונסיב ליה פחר.</p>","notation":[]},"44145":{"h":"פַּחָרָא","r":"KRU15227","alt":[],"source":"krupnik","glosses":[{"text":"potter","label":""}],"html":"<p>יוצר כלי חרס potter  תיג׳ יש׳ כ״ט ט״ז (כהומר היוצר): כמא דטינא ביד פחרא.</p>","notation":["ז׳"]},"44146":{"h":"פָּחַת","r":"KRU15229","alt":[],"source":"krupnik","glosses":[{"text":"to hollow out","label":""},{"text":"to diminish","label":""},{"text":"to be broken through","label":""},{"text":"to be reduced","label":""}],"html":"<p>1) ניקר וחיטט to hollow out  ביצה פ״ד מ״ד: אין פוחתין את הנר. 2) מיעט to diminish  פס׳ פ״י מ״א; ולא יפחתו לו מארבע כוסות. נִפְחַת נפ׳, 1) נשבר קצתו to be broken through  כל׳ פ״ד מ״א: חבית שנפחתה. 2) נתמעט to be reduced  סוטה ה׳ ע״א: לבסוף נפחת. </p>","notation":["פ״י"]},"44147":{"h":"פִּחֵת","r":"KRU15230","alt":[],"source":"krupnik","glosses":[{"text":"to diminish to wear out","label":"פיעל, הפ׳, 1"},{"text":"to be reduced","label":"פיעל, הפ׳, 2"}],"html":"<p>פיעל, הפ׳, הִפְחִית \nפיעל, הפ׳, 1 מיעט to diminish to wear out  תר׳ פ״ד מ״ד: פיחת עשרה או הוסיף עשרה; ירוש׳ ב״מ פ״ח ח׳ ע״ד: אבל לא על ידי האור מפני שמפחיתן.\nפיעל, הפ׳, 2 נתמעט to be reduced  ויק״ר פ״ב: כלום פיחת כבודי; סוכה י״ח ע״ב: הפחית דופן האמצעי.</p>","notation":[]},"44148":{"h":"פְּחַת","r":"KRU15231","alt":[],"source":"krupnik","glosses":[{"text":"to diminish","label":""},{"text":"to be broken","label":""},{"text":"to grow less","label":""}],"html":"<p>1) מיעט, החסיר to diminish  פס׳ קי״ד ע״א: פחות מימכלך וכו׳. 2) נשבר to be broken  ירוש׳ דמ׳ פ״א כ״ב ע״א: פחת פתורא קומוי. אִתְפְּחַת, אִפְּחַת אתפ׳, 1) כנ״ל 2. כת׳ ס״ב ע״א: איפחתא דרגא תותיה; ירוש׳ מו״ק פ״א פ׳ ע״ב: איירא דציפורין איתפחת במועדא. 2) נתמעט to grow less  ילק׳ דב׳ תתצ״ב: איפחת ליה שנה מן שנה. </p>","notation":["פעו״י"]},"44149":{"h":"פְּחָת","r":"KRU15232","alt":[],"source":"krupnik","glosses":[{"text":"broken vessel","label":"1"},{"text":"depreciation","label":"2"}],"html":"<p>1 כלי שבור broken vessel  תוס׳ כל׳ ב״ק ז׳ ט״ו: שילי הפחת.\n2 גרעון depreciation  ירוש׳ תר׳ פ״ד מ״ד ע״ד: שאין הפחת והתוספת שוין.</p>","notation":["ז׳"]},"44150":{"h":"פַּחֲתָא","r":"KRU15233","alt":[],"source":"krupnik","glosses":[{"text":"degraded person","label":"3"}],"html":"<p>1 כנ״ל. 2. ב״מ ע׳ ע״א: שקיל אגרא ושקל פחתא. \n2 עי׳ פּוּחָא 1. תרג׳ מש׳ י״א כ״ט (ינחל רוח): ירית פחתא. \n3 אדם פחות degraded person  ב״ר פל״ו: אבוי דפחתא.</p>","notation":[]},"44151":{"h":"פְּטוֹטֶרֶת","r":"KRU15235","alt":[],"source":"krupnik","glosses":[{"text":"stem","label":""}],"html":"<p>עוקץ stem  ע״ז פ״א מ״ח: בנות שוח ופטוטרותיהן.</p>","notation":["נ׳"]},"44152":{"h":"פְּטוּלְיָיא","r":"KRU15236","alt":[],"source":"krupnik","glosses":[{"text":"basket","label":""}],"html":"<p>סל basket  ירוש׳ מעש״ש פ״א נ״ב ע״ד: פטולייא של תמרים.</p>","notation":["נ׳"]},"44153":{"h":"פְּטוּמָא","r":"KRU15237","alt":[],"source":"krupnik","glosses":[{"text":"crammed bird","label":"1"},{"text":"corpse","label":"2"}],"html":"<p>1 עוף מפיטם crammed bird  מדר׳ תה׳ כ״ג: ייעשה פטומא.\n2 גופה corpse  ירש׳ תענ׳ פ״ד ס״ט ע״א: חמי ליה פטומיה אשכח חכינה כרוכה עליו.</p>","notation":["ז׳"]},"44154":{"h":"פַּטּוּמֵי מִילִי","r":"KRU15238","alt":[],"source":"krupnik","glosses":[{"text":"putting off with fair words","label":""}],"html":"<p>דחיה בקש putting off with fair words  ב״מ ס״ו ע״א: פטומי מילי בעלמא הוא.</p>","notation":["ז״ר"]},"44155":{"h":"פָּטוּר","r":"KRU15240","alt":[],"source":"krupnik","glosses":[{"text":"exempt, free","label":""}],"html":"<p>נקי מחובה exempt, free  ב״מ פ״ז מ״י: פטור משבועה.</p>","notation":["ת׳"]},"44156":{"h":"פִּטּוּר","r":"KRU15241","alt":[],"source":"krupnik","glosses":[{"text":"discharge, exemption","label":""}],"html":"<p>העדר חובה discharge, exemption  שבת ב׳ ע״ב: מהן לחיוב ומהן לפטור.</p>","notation":["ז׳"]},"44157":{"h":"פְּטָטָא","r":"KRU15244","alt":[],"source":"krupnik","glosses":[{"text":"gossip","label":""}],"html":"<p>פטפוט gossip  ב״ר פ״ע: השלום ביניכם לבינו ויאמרו שלום ואין פטטין את בעי והנה רחל וגו׳.</p>","notation":["ז׳"]},"44158":{"h":"פַּטָּטָא","r":"KRU15245","alt":["פַּטָּטָה"],"source":"krupnik","glosses":[{"text":"talkative woman","label":""}],"html":"<p>פטפטנית, דברית talkative woman  ויק״ר פל״ב: דהות פטטא; דב״ר פ״ו: פטטות מנין דכתיב ותדבר מרים.</p>","notation":[]},"44159":{"h":"פְּטָטַרְכָא","r":"KRU15246","alt":[],"source":"krupnik","glosses":[{"text":"rectum","label":""}],"html":"<p>פי הטבעת rectum  ויק״ר פ״ג: ומפטטרכא לברא.</p>","notation":["ז׳"]},"44160":{"h":"פַּטֵּי","r":"KRU15247","alt":[],"source":"krupnik","glosses":[{"text":"to break","label":"פַעל, 1"},{"text":"to relieve","label":"פַעל, 2"}],"html":"<p>פַעל, 1 שבר to break  תרג׳ ירוש׳ בר׳ מ״ט כ״ב: ופטית שיני כל כיפיא.\nפַעל, 2 פטר to relieve  שבת ק״מ ע״ב: דמפטיא ליה תריסר ירחי שתא.</p>","notation":[]},"44161":{"h":"פַּטִּיט","r":"KRU15248","alt":[],"source":"krupnik","glosses":[{"text":"babbler","label":""}],"html":"<p>פטפטן babbler  ב״ר פצ״ג: אני רואה בך שפטיט אתה.</p>","notation":["ז׳"]},"44162":{"h":"פַּטְיָיה","r":"KRU15249","alt":[],"source":"krupnik","glosses":[{"text":"era","label":""}],"html":"<p>מנין שנים era  ירוש׳ סנה׳ פ״י כ״ז ע״ד: הרי הוא נמנה בפטייה של מלכים.</p>","notation":["נ׳"]},"44163":{"h":"פְּטִילְיָיא","r":"KRU15250","alt":["פְּטִילְיָיה"],"source":"krupnik","glosses":[{"text":"basket","label":""}],"html":"<p>נן, סל basket  כל׳ פט״ז מ״ה: פטילייה טמאה וחסינה טהורה; ירוש׳ שבת פט״ו ט״ו ע״א: פטילייא.</p>","notation":[]},"44164":{"h":"פָּטִילִיק","r":"KRU15251","alt":["פָּטִילִיקֵי"],"source":"krupnik","glosses":[{"text":"dish","label":""}],"html":"<p> dish  איכ״ר ג׳ ט״ז: פטיליק דאת מייתי; שם: מהדא פטיליקי.</p>","notation":["ז׳"]},"44165":{"h":"פַּטִּים","r":"KRU15253","alt":[],"source":"krupnik","glosses":[{"text":"stout, fattened","label":"1"},{"text":"perfumed","label":"2"}],"html":"<p>1 מפוטם stout, fattened  ירוש׳ פאה פ״א ט״ו ע״ג: תרנגולין פטימין.\n2 מבושם perfumed  אסת״ר א׳ ג׳: שמא לא יצאת ידי קנדלה פטימא.</p>","notation":["ת׳"]},"44166":{"h":"פַּטִיס","r":"KRU15254","alt":[],"source":"krupnik","glosses":[{"text":"jar","label":""}],"html":"<p>כד jar  איכ״ר ג׳ ט״ז: ומחדא פטיס.</p>","notation":["נ׳"]},"44167":{"h":"פְּטִיקָא","r":"KRU15255","alt":[],"source":"krupnik","glosses":[{"text":"slip of paper","label":""}],"html":"<p>פתקה slip of paper  תרג׳ יב״ע במ׳ י״א כ״ו: בפטיקא כתוביא.</p>","notation":["ז׳"]},"44168":{"h":"פַּטִּיר","r":"KRU15257","alt":[],"source":"krupnik","glosses":[{"text":"pure","label":"1"},{"text":"unleavend","label":"2"},{"text":"first-born","label":"3"}],"html":"<p>1 נקי pure  תרג׳ יח׳ י״ג י׳ (תפל): טין פטיר דלא תבן.\n2 מצה, לא חמץ unleavend  תרג׳ ויק׳ ב׳ ד׳ (רקיקי מצות):אספירין פטירין.\n3 בכור, פטר רחם first-born  גיט׳ ס״ט ע״א: כנתא פטירתא.</p>","notation":["ת׳"]},"44169":{"h":"פְּטִירָה","r":"KRU15258","alt":[],"source":"krupnik","glosses":[{"text":"departure","label":"1"},{"text":"death","label":"2"}],"html":"<p>1 פרידה departure  ביצה ט״ו ע״א: בשעת פטירתן אמר להם לכו אכלו משמנים וגו׳.\n2 מיתה death  אבות פ״ו מ״ט: בשעת פטירתו של אדם.</p>","notation":["נ׳"]},"44170":{"h":"פַּטִּישׁ","r":"KRU15259","alt":[],"source":"krupnik","glosses":[{"text":"a title of honour","label":"1"},{"text":"a man’s name","label":"2"}],"html":"<p>1 תואר כבוד לחכם ומלומד a title of honour  בר׳ כ״ח ע״ב: נר ישראל וכו׳ פטיש החזק.\n2  a man’s name  ב״ב פ״ט ע״ב: ר׳ מני בר פטיש.</p>","notation":[]},"44171":{"h":"פְּטַל","r":"KRU15260","alt":["פְּטַלְיָא","פְּטַלְיָיא"],"source":"krupnik","glosses":[{"text":"basket","label":""}],"html":"<p>סל basket  ירוש׳ דמ׳ פ״א כ״ב ע״א: מיכול עימן ציבחר פטל וכו׳; תוס׳ שבת י״ב (י״ג), ט״ו: פטלייא של גרוגרות; שם מעש״ש א׳ י׳: פטליאות של תמרה.</p>","notation":["ז׳"]},"44172":{"h":"פָּטַם","r":"KRU15261","alt":[],"source":"krupnik","glosses":[{"text":"to fatten","label":""},{"text":"to be fattened","label":""}],"html":"<p>הלעיט to fatten  כת׳ ס״ז ע״א: תרנגולת פטומה. נִפְטַם נפ׳, נאכס to be fattened  ב״ר פל״ב: ומה אם להסגר להפטם וכו׳. </p>","notation":["פ״י"]},"44173":{"h":"פִּטֵּם","r":"KRU15262","alt":[],"source":"krupnik","glosses":[{"text":"to perfume","label":"פיעל, 2"}],"html":"<p>פיעל, 1 עי׳ פָּטַם. ב״ר פפ״ו: פוטיפר שהיה מפטם עגלים לע״ז. \nפיעל, 2 בישם to perfume  כר׳ פ״א מ״א: המפטם את השמן.</p>","notation":[]},"44174":{"h":"פַּטָּם","r":"KRU15263","alt":[],"source":"krupnik","glosses":[{"text":"crammer","label":"1"},{"text":"druggist","label":"2"},{"text":"mast-ox","label":"3"}],"html":"<p>1 מלעיט בעלי־חיים crammer  ביצה ל״ח ע״א: שור של פטם.\n2 רוקח druggist  ירוש׳ סוטה פ״ח כ״ב ע״ג: וכיון שהיה קולט את הריח היה מעבירו כדרך שהפטמין עושין.\n3 שור פטום mast-ox  שבת פ״כ מ״ד: גורפין מלפני הפטם וכו׳.</p>","notation":["ז׳"]},"44175":{"h":"פִּטְמָא","r":"KRU15264","alt":[],"source":"krupnik","glosses":[{"text":"crammed bird","label":""}],"html":"<p>עוף מפוטם crammed bird  שמו״ר פכ״ה: טעם פטמא. ועי׳ פִּיטְמָא.</p>","notation":["ז׳"]},"44176":{"h":"פִּטְמָה","r":"KRU15265","alt":[],"source":"krupnik","glosses":[{"text":"top-piece","label":""}],"html":"<p>עוקץ top-piece  סוכה פ״ג מ״ו: נטלה פטמתו.</p>","notation":["נ׳"]},"44177":{"h":"פְּטָמִים","r":"KRU15266","alt":[],"source":"krupnik","glosses":[{"text":"spices","label":""}],"html":"<p>בשמים spices  תר׳ פי״א מ״ב: לא מנו חכמים שבעה משקים כמוני פטמים.</p>","notation":["ז״ר"]},"44178":{"h":"פִּטְפּוּט","r":"KRU15267","alt":["פִּטְפֵּט"],"source":"krupnik","glosses":[{"text":"peg","label":""}],"html":"<p>כן ובסיס לקדרה peg  כל׳ פ״ו מ״א: העושה שלשה פטפוטים בארץ וחברן בטיט להיות שופת עליהן את הקדרה; תוס׳ שם ב״ק ה׳ א׳: שלשה פטפטין שנתן בארץ.</p>","notation":[]},"44179":{"h":"פִּטְפֵּט","r":"KRU15268","alt":[],"source":"krupnik","glosses":[{"text":"to retort","label":""}],"html":"<p>הטיח דברים to retort  מנ׳ ס״ה ע״א: שוטים מנין לכם ולא היה אדם אחד שהיה משיבו חוץ מזקן אחד שהיה מפטפט כנגדו ואמר וכו׳.</p>","notation":["פ״ע"]},"44180":{"h":"פַּטְפֵּט","r":"KRU15269","alt":[],"source":"krupnik","glosses":[{"text":"to babble","label":""}],"html":"<p>הרבה דברים to babble  ב״ר פצ״ח: דמפטפט צחי.</p>","notation":["פ״ע"]},"44181":{"h":"פִּטְקָא","r":"KRU15270","alt":[],"source":"krupnik","glosses":[{"text":"letter","label":""}],"html":"<p>אגרת letter  תרג׳ אס׳ ח׳ ה׳ (הספרים): פטקיא.</p>","notation":["ז׳"]},"44182":{"h":"פָּטַר","r":"KRU15271","alt":[],"source":"krupnik","glosses":[{"text":"to divorce","label":""},{"text":"to give leave, to let go","label":""},{"text":"to discharge","label":""},{"text":"to be freed","label":""},{"text":"to take leave","label":""},{"text":"to die","label":""}],"html":"<p>1) גירש, נתן גט to divorce  כת׳ פי״ג מ״ה: או כנוס או פטור. 2) נפרד מחבירו to give leave, to let go  סוטה פ״ט מ״ו: ופטרנוהו בלא מזון. 3) שחרר to discharge  יב׳ פ״א מ״א: פוטרות צרותיהן. נִפְטַר נפ׳, 1) נשתחרר to be freed  בכורות פ״ב מ״א: לא נפטרו מבכור. 2) נפרד והלך to take leave  יומא פ״א מ״ה: נפטרו והלכו להם. 3) מת to die  בר׳ י״ז ע״א: נפטר בשם טוב מן העולם. </p>","notation":[]},"44183":{"h":"פִּטֵּר","r":"KRU15272","alt":[],"source":"krupnik","glosses":[{"text":"to dismiss","label":"הִפְטִיר הפ׳, 1"},{"text":"to conclude the reading from the Law by reading a portion of the Prophets","label":"הִפְטִיר הפ׳, 2"},{"text":"to be dismissed","label":"הִתְפַּטֵּר התפ׳,"}],"html":"<p>פיעל, עי׳ פָּטַר 1. גיט׳ ס״ח ע״ב: פטרוה דבריו קיימין פיטרוה לא אמר כלום. \nהִפְטִיר הפ׳, 1 שילח to dismiss  ירוש׳ בר׳ פ״ד ז׳ ע״ד: הפטר את העם.\nהִפְטִיר הפ׳, 2 סיים קריאת התורה ע״י קריאת פרק בנביאים to conclude the reading from the Law by reading a portion of the Prophets  מגי׳ ל׳ ע״א: קורין כי תשא ומפטירין ביהוידע.\nהִתְפַּטֵּר התפ׳, נשלח הביתה to be dismissed  ילק׳ קה׳ תתקפ״ט: בשעה שהתינוקות מתפטרים וכו׳.</p>","notation":[]},"44184":{"h":"פְּטַּר","r":"KRU15273","alt":[],"source":"krupnik","glosses":[{"text":"to depart","label":"1"},{"text":"to let go","label":"2"}],"html":"<p>1 הלך to depart  תרג׳ שה״ש א׳ ז׳: למיפטר מן עלמא.\n2 שילח to let go  תרג׳ יב״ע בר׳ מ״ג י״ד (ושלח לכם את אחיכם): ויפטור ית אחוכון.</p>","notation":["פעו״י"]},"44185":{"h":"פַּטֵּר","r":"KRU15274","alt":[],"source":"krupnik","glosses":[{"text":"to divorce","label":""},{"text":"to deliver a funeral address","label":""},{"text":"to take leave","label":""},{"text":"to be sent off","label":""},{"text":"to be divorced","label":""},{"text":"to be exempted","label":""}],"html":"<p>גירש, נתן גט to divorce  תרג׳ קהל׳ ז׳ כ״ו: גבר די יפטיר יתה בגט פטורין. אַפְטַר  אפ׳, 1) עי׳ פְּטַר 2. במ״ר פי״ב: דיהוון מפטירין טלייא. 2) הספיד to deliver a funeral address  ירוש׳ בר׳ פ״ב ח׳ ע״ב: כד דמך ר׳ בון בר ר׳ חייא על ר׳ זעירא ואפטר עילוי. 3) נפרד והלך to take leave  תנח׳ בראש׳ י״ג: אפטרו מיניה באורתא. 4) עי׳ הִפְטִיר 2. מגי׳ ל׳ ע״ב: קרא ומפטרי. אִתְפְּטַר, אִיפַּטַּר אתפ׳, 1) נשתלח to be sent off  תרג׳ בר׳ מ״ד ג׳ (והאנשים שולחו): וגובריא אתפטרו. 2) נתגרשה האשה to be divorced  תרג׳ יב״ע ויק׳ כ״א י״ד (אלמנה וגרושה): ארמלא ומיפטרא. 3) נפטר, נשתחרר to be exempted  בכורות ד׳ ע״א: אפי׳ מבכור בהמה נטי ניפטרו. </p>","notation":["פעל"]},"44186":{"h":"פטר בולי","r":"KRU15275","alt":[],"source":"krupnik","glosses":[{"text":"chief senatores","label":""}],"html":"<p>ראשי העיר או המדינה chief senatores  ירוש׳ קיד׳ פ״א ס״א ע״ב: פטר בולי.</p>","notation":["ז״ר","Source emendation: פַּטְרוֹבוּלֵי"]},"44187":{"h":"פַּטְרוֹזָא","r":"KRU15276","alt":[],"source":"krupnik","glosses":[{"text":"a puny lamb","label":""}],"html":"<p>שה רזה a puny lamb  בכורות י״א ע״א: אפילו פטרוזא בר דנקא.</p>","notation":["ז׳"]},"44188":{"h":"פַּטְרוֹן","r":"KRU15278","alt":[],"source":"krupnik","glosses":[{"text":"protector","label":""}],"html":"<p>מגין protector  תנח׳ וישב ח׳: אתה הוא בטחוני אתה הוא פטרוני.</p>","notation":["ז׳"]},"44189":{"h":"פִּטְרוֹס","r":"KRU15279","alt":[],"source":"krupnik","glosses":[{"text":"a man’s name","label":"1"},{"text":"name of a place","label":"2"}],"html":"<p>1  a man’s name  ב״ר פצ״ב: ר׳ יוסי בר פטרוס.\n2  name of a place  תוס׳ דמ׳ א׳ י״א: ושוק של פטרוס.</p>","notation":[]},"44190":{"h":"פַּטְרוֹפּוֹלִי","r":"KRU15280","alt":["פטרופלי"],"source":"krupnik","glosses":[{"text":"chief senators","label":""}],"html":"<p>ראשי העיר או המדינה chief senators  פסיק׳ ולקחתם קפ״ב ע״ב: יצאו פטרופולי וקילסו אותו; ילק׳ ויק׳ תרנ״א: פטרופלי המדינה.</p>","notation":[]},"44191":{"h":"פַּטְרוֹקִי","r":"KRU15281","alt":[],"source":"krupnik","glosses":[{"text":"name of an Amora","label":""}],"html":"<p>שם אמורא name of an Amora  ירוש׳ יומא פ״ד מ״א ע״ד: ר׳ פטרוקי אחוה דר׳ דרוסא.</p>","notation":[]},"44192":{"h":"פִּטְרִיּוֹת","r":"KRU15282","alt":[],"source":"krupnik","glosses":[{"text":"truffles","label":""}],"html":"<p>מין צמח ספוגי ולח, שאין לו שורש truffles  עוקצ׳ פ״ג מ״ב: ושאר כל ירקות שדה חוץ משמרקעים ופטריות.</p>","notation":["נ״ר"]},"44193":{"h":"פַּטְרִיקוֹן","r":"KRU15283","alt":[],"source":"krupnik","glosses":[{"text":"patrimony","label":""}],"html":"<p>נחלת אבות patrimony  במ״ר פ״כ: פטריקון שלנו שנאמר הקול קול יעקב וכו׳ פטריקון שלי.</p>","notation":["ז׳"]},"44194":{"h":"פטרכולי","r":"KRU15285","alt":[],"source":"krupnik","glosses":[{"text":"chief senators","label":""}],"html":"<p>ראשי העיר או המדינה chief senators  ירוש׳ פאה פ״א ט״ו ע״ג: ראש פטרכולי היה.</p>","notation":["ז״ר","Source emendation: פַּטְרוֹבוּלֵי"]},"44195":{"h":"פִּי","r":"KRU15287","alt":[],"source":"krupnik","glosses":[{"text":"rectum","label":""}],"html":"<p>עי׳ פֶּה ·– פִּי הַטַּבַּעַת המעי התחתון המיועד להוצאת הרעי rectum  שבת ק״ח ע״ב: יד לפי טבעת תיקצץ.</p>","notation":[]},"44196":{"h":"פִּי מְצוֹבָה","r":"KRU15288","alt":[],"source":"krupnik","glosses":[{"text":"name of a place","label":""}],"html":"<p>name of a place  ירוש׳ דמ׳ פ״ב כ״ב ע״ד: אילו עיירות אסורות בתחום צור שיצת ובצת ופי מצובה. </p>","notation":["שם מקום"]},"44197":{"h":"פִּיאָבִי","r":"KRU15289","alt":[],"source":"krupnik","glosses":[{"text":"a woman’s name","label":""}],"html":"<p>שם אשה a woman’s name  ירוש׳ יומא פ״ג מ׳ ע״ד: ר׳ ישמעל בן פיאבי.</p>","notation":[]},"44198":{"h":"פִּיָאלִי","r":"KRU15290","alt":[],"source":"krupnik","glosses":[{"text":"bowl","label":""}],"html":"<p>כוס bowl  תנח׳ נשא א׳: פיאלי של חרש.</p>","notation":["נ׳"]},"44199":{"h":"פִּיגוּר","r":"KRU15293","alt":[],"source":"krupnik","glosses":[{"text":"destruction","label":""}],"html":"<p>הרס וחורבן destruction  תרג׳ יש׳ כ״ה י״ב (יכת שער): פיגור תרעין.</p>","notation":["ז׳"]},"44200":{"h":"פִּיגִי","r":"KRU15294","alt":[],"source":"krupnik","glosses":[{"text":"spring","label":""}],"html":"<p>מעין spring  ב״ר פס״ו: כפיגי שהיא נתונה בגן ומשקה את הגן.</p>","notation":["נ׳"]},"44201":{"h":"פִּיגָם","r":"KRU15296","alt":[],"source":"krupnik","glosses":[{"text":"rue","label":""}],"html":"<p>מין צמח rue  כלא׳ פ״א מ״ח: אין מרכיבין פיגם ע״ג קדה לבנה מפני שהוא ירק באילן.</p>","notation":["ז׳"]},"44202":{"h":"פִּידְגּוּגְתָּא","r":"KRU15300","alt":[],"source":"krupnik","glosses":[{"text":"nurse","label":""}],"html":"<p>מחנכת nurse  תרג׳ יב״ע בר׳ ל״ה ח׳ (מינקת רבקה): פידגוגתא דרבקה.</p>","notation":["נ׳"]},"44203":{"h":"פִּידְעָה","r":"KRU15302","alt":[],"source":"krupnik","glosses":[{"text":"wound","label":""}],"html":"<p>פצע wound  תרג׳ שמ׳ כ״א כ״ה (פצע תחת פצע): פידעא חלף פידעא.</p>","notation":["ז׳"]},"44204":{"h":"פִּיו","r":"KRU15303","alt":[],"source":"krupnik","glosses":[{"text":"fringe","label":""}],"html":"<p>גדיל fringe  כלא׳ פ״ט מ״ט: פיו של צמר בשל פשתן אסור.</p>","notation":["ז׳"]},"44205":{"h":"פִּיוְולָא","r":"KRU15304","alt":[],"source":"krupnik","glosses":[{"text":"an upper-garment","label":""}],"html":"<p>מין בגד עליון an upper-garment  תנח׳ בובר נח כ״א: נתן וכו׳ טלית לשֵם וליפת פיוולא.</p>","notation":["נ׳"]},"44206":{"h":"פִּיוּט","r":"KRU15305","alt":[],"source":"krupnik","glosses":[{"text":"fiction","label":""}],"html":"<p>שירה fiction  ב״ר פפ״ה: שלא יאמרו דברי פיוטין הן.</p>","notation":["ז׳"]},"44207":{"h":"פְּיוּטוֹת","r":"KRU15306","alt":[],"source":"krupnik","glosses":[{"text":"little children","label":""}],"html":"<p>טף, קטנים little children  ירוש׳ עיר׳ פ״ז כ״ד ע״ג: הפיוטות מקחן מקח.</p>","notation":["ז״ר"]},"44208":{"h":"פְּיוֹלִי","r":"KRU15307","alt":[],"source":"krupnik","glosses":[{"text":"bowl","label":""}],"html":"<p>קערה bowl  תרג׳ יב״ע במ׳ ז׳ י״ג (קערה): פיולי.</p>","notation":["נ׳"]},"44209":{"h":"פִּיוּס","r":"KRU15308","alt":["פִּיוּסָא"],"source":"krupnik","glosses":[{"text":"conciliation","label":""}],"html":"<p>ריצוי, פיצוי conciliation  ירוש׳ תענ׳ פ״ב ס״ה ע״ב: בני המדינה מקלסין אותי ואני מקבל פיוסן; ב״ר פצ״ד: אגב פיוסא וכו׳.</p>","notation":[]},"44210":{"h":"פֵּיוְסָרוֹס","r":"KRU15309","alt":[],"source":"krupnik","glosses":[{"text":"name of a tortuous street","label":""}],"html":"<p>שם רחוב מעוקם ומפותל name of a tortuous street  ירוש׳ עיר׳ פ״ח כ״ה ע״ב: אהן פיוסרוס זרק מתוכה.</p>","notation":[]},"44211":{"h":"פִּיזָא","r":"KRU15310","alt":["פִּיזוּזָא"],"source":"krupnik","glosses":[{"text":"fine gold","label":""}],"html":"<p>פז fine gold  תרג׳ איוב כ״ח י״ח (כלי פז): מיאני פיזוזא; כת׳ ע״ז ע״ב: תכטקי פיזא.</p>","notation":[]},"44212":{"h":"פִּיזוּר","r":"KRU15311","alt":[],"source":"krupnik","glosses":[{"text":"scattering","label":""}],"html":"<p>זירוי והפצה scattering  טבול יום ב׳ ג׳: אם היה מפוזר במדוכה טהור מפני שהוא רוצה בפיזורו.</p>","notation":["ז׳"]},"44213":{"h":"פִּיזְמָא","r":"KRU15312","alt":[],"source":"krupnik","glosses":[{"text":"hymn","label":""}],"html":"<p>מזמור, פזמון hymn  פסיק׳ החודש ק״א ע״ב: פיזמא דידיה הוא סליקת ביה למיתן לי אוריתא.</p>","notation":["ז׳"]},"44214":{"h":"פִּיזְמִיקוֹן","r":"KRU15313","alt":["פִּיזְמָרִיקוֹן"],"source":"krupnik","glosses":[{"text":"patrimony","label":""}],"html":"<p>מה שמתנחל בדרך הטבע מאבות לבנים patrimony  מדר׳ תה׳ י״ח מ״א: פיזמריקון שלי הוא שנאמר וזאת ליהודה; ילק׳ שמואל קס״ג: פיזמיקון.</p>","notation":[]},"44215":{"h":"פִּיחָה","r":"KRU15314","alt":[],"source":"krupnik","glosses":[{"text":"convulsion","label":"1"},{"text":"expectoration","label":"2"},{"text":"flatulence","label":"3"}],"html":"<p>1 זעזוע convulsion  שמו״ר פמ״ג: ישראל שנתנו פיחה בעולם בעגל שעשו.\n2 הקאה expectoration  ירוש׳ עיר׳ פ״י כ״ו ע״ב: רב אמר בפיחה.\n3 הוצאת אדים flatulence  ע״ז י״ז ע״א: כשם שהפיחה הזו אינה חוזרת למקומה.</p>","notation":["נ׳"]},"44216":{"h":"פִּיחָם","r":"KRU15315","alt":[],"source":"krupnik","glosses":[{"text":"coal","label":""}],"html":"<p>פחם, גחלת coal  תוס׳ מעש״ש ה׳ י״ג: בית ע״ז מפחמין אותו בפיחמין.</p>","notation":["ז׳"]},"44217":{"h":"פִּיטוּם","r":"KRU15318","alt":["פִּיטוּמָא"],"source":"krupnik","glosses":[{"text":"compounding ingredients","label":""}],"html":"<p>ריקוח, הרכבת בשמים compounding ingredients  כר׳ ו׳ ע״א: פיטום הקטורת וכו׳; שם ג׳ ע״א: בעי למיתנא פיטומין בהדי הדדי.</p>","notation":[]},"44218":{"h":"פִּיטוֹמֶת","r":"KRU15319","alt":[],"source":"krupnik","glosses":[{"text":"nipple","label":""}],"html":"<p>עוקץ שבדד האשה nipple  נדה מ״ז ע״א: משישחירו הפיטומות.</p>","notation":["נ׳"]},"44219":{"h":"פִּיטוּס","r":"KRU15320","alt":[],"source":"krupnik","glosses":[{"text":"barrel","label":""}],"html":"<p>חבית barrel  כת׳ קי״א ע״ב: מסתפק הימנה כפיטוס גדול.</p>","notation":["ז׳"]},"44220":{"h":"פִּיטוּרָה","r":"KRU15321","alt":[],"source":"krupnik","glosses":[{"text":"stone-wall","label":""}],"html":"<p>קיר אבן stone-wall  ירוש׳ כלא׳ פ״א כ״ז ע״ב: על גבי פיטורה על גבי סלעים.</p>","notation":["נ׳"]},"44221":{"h":"פִּיטוּרֵי","r":"KRU15322","alt":[],"source":"krupnik","glosses":[{"text":"ropes","label":""}],"html":"<p>חבלים, עבותות ropes  בר׳ ח׳ ע״א: כפיטורי בפי ושט.</p>","notation":["ז״ר"]},"44222":{"h":"פִּטוּרִין²","r":"KRU15323","alt":[],"source":"krupnik","glosses":[{"text":"divorce","label":""}],"html":"<p>גירושין divorce  גיט׳ פ״ט מ״ג: גט פיטורין.</p>","notation":["ז״ר"]},"44223":{"h":"פִּיטְטָא","r":"KRU15324","alt":[],"source":"krupnik","glosses":[{"text":"talk","label":""}],"html":"<p>פטפוט talk  ויק״ר פי״ב: למאן פיטטין.</p>","notation":["ז׳"]},"44224":{"h":"פִּיטְמָא","r":"KRU15327","alt":[],"source":"krupnik","glosses":[{"text":"fatness","label":"1"},{"text":"top-piece","label":"2"}],"html":"<p>1  fatness  ב״ק מ״ז ע״א: פיטמא לבעל חפרה.\n2 עוקץ שבראש הפרי top-piece  עוקצ׳ פ״ב מ״ג: הפיטמא של רמון.</p>","notation":[]},"44225":{"h":"פִּיטְרָא","r":"KRU15332","alt":[],"source":"krupnik","glosses":[{"text":"fungus","label":""}],"html":"<p>פטריה fungus  שבת ק״ז ע״ב: האי מאן דתלש פיטרא.</p>","notation":["ז׳"]},"44226":{"h":"פִּיטְרוֹסִילִינוֹן","r":"KRU15335","alt":[],"source":"krupnik","glosses":[{"text":"rock-parsley","label":""}],"html":"<p>מין כרפס rock-parsley  ירוש׳ שבי׳ פ״ט ל״ח ע״ג: כרפס שבנהרות – פיטרוסילינון.</p>","notation":["ז׳"]},"44227":{"h":"פִּיטְרָס","r":"KRU15339","alt":[],"source":"krupnik","glosses":[{"text":"a man’s name","label":""}],"html":"<p>a man’s name  ירוש׳ מו״ק פ״ג פ״ב ע״ד: ר׳ יוסי בר פיטרס. </p>","notation":["שם איש"]},"44228":{"h":"פייטוי","r":"KRU15341","alt":["פַּיְיטָן","פַּיְיטָנָא"],"source":"krupnik","glosses":[{"text":"poet","label":""}],"html":"<p>משורר poet  ויק״ר פ״ל: פייטן ודרשן; שהש״ר ג׳ ו׳: פייטוי; שם א׳ א׳: הדין פייטנא.</p>","notation":[]},"44229":{"h":"פְּיָילָא","r":"KRU15342","alt":["פַּיְילִי"],"source":"krupnik","glosses":[{"text":"cup, bowl","label":""}],"html":"<p>כוס, קערה cup, bowl  תרג׳ יב״ע בד׳ מ׳ י״ב: פיילא דרוגזא; תרג׳ ירוש׳ במ׳ ז׳ י״ג (קערה): פיילי.</p>","notation":[]},"44230":{"h":"פַּיְילָן","r":"KRU15343","alt":[],"source":"krupnik","glosses":[{"text":"cup-bearer","label":""}],"html":"<p>מוזג cup-bearer  קהל״ר ג׳ ט׳: והוה פיילן נהיג מעתיר ליה חד משקויי חמים בכל יום.</p>","notation":["ז׳"]},"44231":{"h":"פַּיְילָתָא","r":"KRU15344","alt":[],"source":"krupnik","glosses":[{"text":"bowl","label":""}],"html":"<p>קערה bowl  תרג׳ ירוש׳ במ׳ ז׳ פ״ה: פיילתא ומזרקא.</p>","notation":["נ׳"]},"44232":{"h":"פַּיִּיס","r":"KRU15345","alt":[],"source":"krupnik","glosses":[{"text":"allotment","label":""}],"html":"<p>גורל, הגרלה allotment  יומא פ״ב מ״ב: זה הפייס הראשון.</p>","notation":["ז׳"]},"44233":{"h":"פַּיְיסָא","r":"KRU15346","alt":[],"source":"krupnik","glosses":[{"text":"peace","label":"2"}],"html":"<p>1 כנ״ל. יומא כ״ב ע״א: תקינו לה פייסא. \n2 שלום peace  נדה ל״ז ע״א: עבדו רבנן פייסא.</p>","notation":["ז׳"]},"44234":{"h":"פַּיְיסוֹנָא","r":"KRU15347","alt":[],"source":"krupnik","glosses":[{"text":"mason","label":""}],"html":"<p>בנאי mason  ירוש׳ יב׳ פי״ב י״ג ע״א: הדין פייסונא וכו׳.</p>","notation":["ז׳"]},"44235":{"h":"פִּיל","r":"KRU15348","alt":[],"source":"krupnik","glosses":[{"text":"elephant","label":"1"},{"text":"soaked, permeated","label":"2"}],"html":"<p>1  elephant  כלא׳ פ״ח מ״ו: הפיל והקוף מין חיה.\n2  soaked, permeated  תרג׳ ויק׳ י״ד כ״א (בלול בשמן): דפיל במשח.</p>","notation":[]},"44236":{"h":"פִּילָא","r":"KRU15349","alt":[],"source":"krupnik","glosses":[{"text":"crack, split","label":"3"},{"text":"an aromatic plant","label":"4"},{"text":"old","label":"6"}],"html":"<p>1 כנ״ל 1. בר׳ נ״ה ע״ב: פילא דעייל בקופא דמחטא. \n2 כנ״ל 2. תרג׳ ויק׳ י״ד י׳ (בלולה בשמן): דפילא במשח. \n3 חריץ, סדק crack, split  ב״ב נ״ד ע״א: דשדא ליפתא בי פילי דארעא.\n4 מין בושם an aromatic plant  כת׳ ע״ז ע״ב: פילא ולודנא.\n5 עי׳ פִּילֵי. תנה׳ מקץ י׳: הושיב שומרים על פתחי פילאות. \n6  old  ויק״ר פל״ג: פילא פורני.</p>","notation":[]},"44237":{"h":"פֵּילָגוֹס","r":"KRU15350","alt":[],"source":"krupnik","glosses":[{"text":"offing","label":""}],"html":"<p>לב ים offing  קהל״ר ג׳ ו׳: כד עללין אנן לפילגוס אנן קטלינן ליה.</p>","notation":["ז׳"]},"44238":{"h":"פִּילָה","r":"KRU15351","alt":[],"source":"krupnik","glosses":[{"text":"bean","label":"1"},{"text":"a man’s name","label":"2"}],"html":"<p>1 פול bean  ירוש׳ כלא׳ פ״א כ״ז ע״א: פילה פושונא גילבונה וכו׳.\n2 שם איש a man’s name  ירוש׳ בר׳ פ״ט י״ד ע״ב: יודן בן פילה.</p>","notation":["ז׳"]},"44239":{"h":"פִּילוּג","r":"KRU15352","alt":[],"source":"krupnik","glosses":[{"text":"division","label":""}],"html":"<p>חלוקה division  ירוש׳ בר׳ פ״א ב׳ ע״ג: וכל פילוג מי בראשית מתפלגין מתחתיו.</p>","notation":["ז׳"]},"44240":{"h":"פִּילוֹטִימְיָא","r":"KRU15353","alt":[],"source":"krupnik","glosses":[{"text":"public show","label":""}],"html":"<p>מחזה פומבי public show  שמו״ר פ״ל: שמע שפילוטימיא נעשית במדינה.</p>","notation":["נ׳"]},"44241":{"h":"פִּילוּל","r":"KRU15354","alt":[],"source":"krupnik","glosses":[{"text":"pleading, prayer","label":""}],"html":"<p>תפלה ותחנה pleading, prayer  דב״ר פ״ב: פילול דכתיב ויעמוד פנחס ויפלל.</p>","notation":["ז׳"]},"44242":{"h":"פִּילוֹמָא","r":"KRU15355","alt":[],"source":"krupnik","glosses":[{"text":"mud","label":""}],"html":"<p>טיט mud  ירוש׳ שבת פכ״ב מ״ו: אין יורדין לפילומא.</p>","notation":["ז׳"]},"44243":{"h":"פִּילוֹן","r":"KRU15356","alt":[],"source":"krupnik","glosses":[{"text":"aromatic leaves","label":"1"},{"text":"gateway","label":"2"}],"html":"<p>1 מין בושם aromatic leaves  ספרא ויקרא חובה פרשה י״ב פרק כ״ב: המערב וכו׳ עלי גפנים בפילון.\n2 מבוא, שער gateway  ויק״ר פ״ל: איזה פילון מפולש לחיי עוה״ב.</p>","notation":["ז׳"]},"44244":{"h":"פִּילוֹסוֹפוֹס","r":"KRU15357","alt":[],"source":"krupnik","glosses":[{"text":"philosopher","label":""}],"html":"<p>חכם, חוקר philosopher  ירוש׳ שבת פ״ג ו׳ ע״א: חד פילוסופוס שאל לבר קפרא.</p>","notation":["ז׳"]},"44245":{"h":"פִּילוּסִין","r":"KRU15358","alt":[],"source":"krupnik","glosses":[{"text":"Pelusium in Egypt","label":"1"},{"text":"Pelusian linen","label":"2"}],"html":"<p>1 עיר במצרים Pelusium in Egypt  תרג׳ יב״ע בר׳ מ״ז י״א: (ארץ רעמסס): ארעא דפילוסין.\n2 מין בד מעיר פילוסין Pelusian linen  ירוש׳ יומא פ״ג מ׳ ע״ד: ואין שני של פילוסין יפה מן הראשון של הנדוין.</p>","notation":[]},"44246":{"h":"פִּילוֹספוֹס","r":"KRU15359","alt":[],"source":"krupnik","glosses":[{"text":"a man’s name","label":""}],"html":"<p>a man’s name  ע״ז פ״ג מ״ד: פרוקלוס בן פילוספוס. </p>","notation":["שם איש"]},"44247":{"h":"פִּילְחָא","r":"KRU15360","alt":[],"source":"krupnik","glosses":[{"text":"millstone","label":""}],"html":"<p>פלח הרכב של ריחיים millstone  ירוש׳ מו״ק פ״א פ׳ ע״ד: אית לן פילחא דמועדא.</p>","notation":["ז׳"]},"44248":{"h":"פִּילֵי","r":"KRU15362","alt":[],"source":"krupnik","glosses":[{"text":"gate","label":""}],"html":"<p>שער gate  ירוש׳ יב׳ פי״ב י״ב ע״ד: מן דמטון פילי א״ל רבי זעירא ההן פתח חצירך.</p>","notation":["נ׳"]},"44249":{"h":"פִּילְכָא","r":"KRU15365","alt":[],"source":"krupnik","glosses":[{"text":"district","label":"1"},{"text":"spindle","label":"2"}],"html":"<p>1 פלך, מחוז district  תרג׳ יח׳ י״ז י״א (הנפת): תלתא פילכין.\n2 כלי המטוה spindle  מגי׳ י״ד ע״ב: אתתא בהדי שותא פילכא (בהו׳ אח׳: פילכה).</p>","notation":["ז׳"]},"44250":{"h":"פִּילֵס","r":"KRU15367","alt":[],"source":"krupnik","glosses":[{"text":"a weight","label":""}],"html":"<p>מין משקל a weight  תרג׳ יחז׳ ד׳ י׳ (עשרים שקל): עשרין פילס.</p>","notation":["ז׳"]},"44251":{"h":"פִּילְפִּי","r":"KRU15369","alt":[],"source":"krupnik","glosses":[{"text":"name of an Amora","label":""}],"html":"<p>שם אמורא name of an Amora  ירוש׳ מגי׳ פ״ד ע״ה ע״א: ר׳ פילפי בר פרטה.</p>","notation":[]},"44252":{"h":"פִּילָקִי","r":"KRU15372","alt":[],"source":"krupnik","glosses":[{"text":"prison","label":""}],"html":"<p>משמר, תפיסה prison  שמו״ר פט״ו: למטרונה שהיתה מקטרגת למלך נתנה בפילקי.</p>","notation":["נ׳"]},"44253":{"h":"פִּילְקִין","r":"KRU15373","alt":["פִּילְקִיס"],"source":"krupnik","glosses":[{"text":"axe","label":""}],"html":"<p>גרזן axe  שמו״ר פי״ב: יורד כפילקין וקוצץ את האילנות; מדר׳ תה׳ ק״ה ל״ג: כפילקיס הזה היה יורד הברד עליהם.</p>","notation":[]},"44254":{"h":"פִּילַקְתָּא","r":"KRU15374","alt":[],"source":"krupnik","glosses":[{"text":"concubine","label":""}],"html":"<p>פילגש concubine  תרג׳ יב״ע בר׳ ל״ו י״ב (פילגש): פילקתא.</p>","notation":["נ׳"]},"44255":{"h":"פִּינוּכָא","r":"KRU15375","alt":[],"source":"krupnik","glosses":[{"text":"speeding","label":""}],"html":"<p>דהרה speeding  תרג׳ שופ׳ ה׳ כ״ב (מדהרות דהרות אביריו): מפינוכא דהוה מפניך.</p>","notation":["ז׳"]},"44256":{"h":"פִּינוֹן","r":"KRU15376","alt":[],"source":"krupnik","glosses":[{"text":"felt","label":""}],"html":"<p>לבד felt  כלא׳ פ״ט מ״ז: מנעלות הפינון.</p>","notation":["ז׳"]},"44257":{"h":"פִּינוּקָא","r":"KRU15378","alt":[],"source":"krupnik","glosses":[{"text":"pleasure","label":""}],"html":"<p>תענוג pleasure  תרג׳ מש׳ י״ט י׳ (תענוג): פינוקא.</p>","notation":["ז׳"]},"44258":{"h":"פִּינָךְ","r":"KRU15379","alt":["פִּינְכָא"],"source":"krupnik","glosses":[{"text":"dish","label":""}],"html":"<p>קערה dish  ירוש׳ סנה׳ פי״א ל׳ ע״ג: פינך דסולת; תענ׳ כ״ד ע״ב: פינכא דדייסא.</p>","notation":[]},"44259":{"h":"פֵּינַס","r":"KRU15380","alt":[],"source":"krupnik","glosses":[{"text":"a cloak","label":""}],"html":"<p>מין בגד a cloak  ב״ר פפ״ד: ויפשיטו – זה הפינס.</p>","notation":["ז׳"]},"44260":{"h":"פינסור","r":"KRU15381","alt":[],"source":"krupnik","glosses":[{"text":"guard","label":""}],"html":"<p>שומר guard  תנה׳ שופ׳ י׳: והיה הפינסור שלה עומד על פתח המדינה.</p>","notation":["ז׳","Source emendation: קוּסְטוֹר"]},"44261":{"h":"פִּינְקַאי","r":"KRU15382","alt":[],"source":"krupnik","glosses":[{"text":"a man’s name","label":""}],"html":"<p>a man’s name  כר׳ כ״ח ע״א: יוחנן בן נדבאי תלמידו של פינקאי. </p>","notation":["ז׳ שם איש"]},"44262":{"h":"פִּיֵּס","r":"KRU15384","alt":[],"source":"krupnik","glosses":[{"text":"to pacify, to conciliate","label":"פיעל,"},{"text":"to loosen","label":"הֵפִיס הפ׳, 2"},{"text":"to distinguish","label":"הֵפִיס הפ׳, 3"},{"text":"to decide by lots","label":"הֵפִיס הפ׳, 4"},{"text":"to be appeased","label":"הִתְפַּיֵּס התפ׳,"}],"html":"<p>פיעל, ריצה, פיצה, שידל to pacify, to conciliate  ב״ר פצ״ג: לא פייס יוסף את אחיו אלא בבכיה.\nהֵפִיס הפ׳, 1 כנ״ל. שבוע׳ מ״ה ע״א: כדי להפיס דעתו. \nהֵפִיס הפ׳, 2 הסיר to loosen  כת׳ ו׳ ע״א: המפיס מורסא וכו׳.\nהֵפִיס הפ׳, 3 הבחין to distinguish  שבת נ״ד ע״א: מי מפיס איזו ליבש ואיזו לחלב.\nהֵפִיס הפ׳, 4 הכריע ע״י גורל to decide by lots  תמיד פ״א מ״ב: הפיסו זכה מי שזכה.\nהִתְפַּיֵּס התפ׳, נתרצה to be appeased  יומא פ״ו ע״ב: בשר ודם מקניט את חבירו בדברים ספק מתפייס ספק אינו מתפייס.</p>","notation":[]},"44263":{"h":"פַּיֵּס","r":"KRU15385","alt":[],"source":"krupnik","glosses":[{"text":"to pray","label":""},{"text":"to desecrate","label":""},{"text":"to be degraded","label":""}],"html":"<p>1) עי׳ פִּיֵּס. תרג ש״א כ״ד ח׳ (וישסע דוד את אנשיו בדברים): ופייס דוד ית גברוהי בפתגמיא. 2) בקש רחמים to pray  תרג׳ יב״ע בר׳ מ״ב כ״א (בהתחננו אלינו): כד הוא מפייס לנא. אָפֵיס  אפ׳, חילל to desecrate  תרג׳ יב״ע ויק׳ כ״א ה׳ (כי תחל): ארום תפיס. אִיתְּפִיס, אִיפַּיֵּס אתפ׳, 1) נתחלל to be degraded  תרג׳ יב״ע דב׳ כ״ג י״ח: ולא יתפס ית גרמיה. 2) עי׳ הִתְפַּיֵּס. בס״ר פ״ה: מאן פייסך דאיפייסת. </p>","notation":["פַעל"]},"44264":{"h":"פִּיסָא","r":"KRU15386","alt":[],"source":"krupnik","glosses":[{"text":"los","label":"1"},{"text":"lump","label":"2"},{"text":"bread","label":"3"}],"html":"<p>1 גורל los  תרג׳ אס׳ ט׳ כ״ד (הפיל פור): צבע פיסא.\n2 גוש אדמה lump  סנה׳ ס״ד ע״א: שקל פיסא שדא ביה.\n3 פת bread  ירוש׳ בר׳ פ״ו י׳ ע״ב: הדין פיסא.</p>","notation":["ז׳"]},"44265":{"h":"פִּיסְגָּא","r":"KRU15387","alt":[],"source":"krupnik","glosses":[{"text":"piece","label":""}],"html":"<p>חתיכה piece  ירוש׳ נד׳ פ״ד ל״ה ע״ד: תמחוי החוזר – פיסגתא.</p>","notation":["נ׳"]},"44266":{"h":"פִּיסָה","r":"KRU15388","alt":[],"source":"krupnik","glosses":[{"text":"palm of the hand or the foot","label":""}],"html":"<p>כף יד או רגל palm of the hand or the foot  אהל׳ פ״א מ״ח: בפיסת הרגל וכו׳ בפיסת היד.</p>","notation":["ז׳"]},"44267":{"h":"פִּיסוּגָא","r":"KRU15389","alt":[],"source":"krupnik","glosses":[{"text":"piece","label":""}],"html":"<p>חתיכה piece  תרג׳ ויק׳ כ״ו מ״ב: ביני פיסוגיא.</p>","notation":["ז׳"]},"44268":{"h":"פִּיסוּל","r":"KRU15390","alt":[],"source":"krupnik","glosses":[{"text":"cutting off","label":""}],"html":"<p>קציצה cutting off  שבי׳ פ״ב מ״ג: כל זמן שאני רשאי בעבודת האילן רשאי אני בפיסולו.</p>","notation":["ז׳"]},"44269":{"h":"פִּיסוֹן","r":"KRU15392","alt":[],"source":"krupnik","glosses":[{"text":"mason","label":""}],"html":"<p>בנאי mason  כל׳ פ״כ מ״ב: עריבת פיסונות.</p>","notation":["ז׳"]},"44270":{"h":"פִּיסוּק","r":"KRU15393","alt":[],"source":"krupnik","glosses":[{"text":"separation, interruption","label":"1"},{"text":"setting a price","label":"2"},{"text":"spreading, straddling","label":"3"}],"html":"<p>1 הפסקה separation, interruption  זב׳ נ״ג ע״ב: פיסוק ארבע מתנות.\n2 קביעת המחיר setting a price  ירוש׳ ב״מ פ״ה י׳ ע״ג: בפיסוק איתפלגון.\n3 פישוק, פתיחה לרוחה spreading, straddling  כת׳ ל״ט ע״ב: צער של פיסוק הרגלים.</p>","notation":["ז׳"]},"44271":{"h":"פִּיסוּק טְעָמִים","r":"KRU15394","alt":[],"source":"krupnik","glosses":[{"text":"punctuation marks","label":""}],"html":"<p>סימני ההפסק במקרא, נגינות punctuation marks  נדר׳ ל״ז ע״א: פיסוק טעמים.</p>","notation":[]},"44272":{"h":"פִּיסְטִין","r":"KRU15395","alt":["פִּיסְטִיס"],"source":"krupnik","glosses":[{"text":"trust","label":""}],"html":"<p>אמנה, אשראי trust  ילק׳ תה׳ תרע״ב: ופורעין בפיסטין; ירוש׳ כת׳ פ״ב כ״ו ע״ב: שטר אמנה ושטר פיסטיס הוא.</p>","notation":[]},"44273":{"h":"פִּיסְטַלְיוֹת","r":"KRU15396","alt":[],"source":"krupnik","glosses":[{"text":"epistyles","label":""}],"html":"<p>קורות שעל גבי עמודים epistyles  ירוש׳ סוכה פ״א נ״ב ע״ב: ארבעה עמודים ועליהם ארבע פיסטליות.</p>","notation":["נ״ר"]},"44274":{"h":"פִּיסְטְקָא","r":"KRU15397","alt":[],"source":"krupnik","glosses":[{"text":"pistachio-nut","label":""}],"html":"<p>מין אגוז pistachio-nut  ירוש׳ בלא׳ פ״א כ״ז ע״א: מה נפיק מביניהון – פיסטקין.</p>","notation":["ז׳"]},"44275":{"h":"פִּיסִין","r":"KRU15399","alt":[],"source":"krupnik","glosses":[{"text":"a Roman tax","label":""}],"html":"<p>מין מס a Roman tax  ירוש׳ פאה פ״א ט״ו ע״ב: אם נתת מכיסך צדקה הקב״ה משמרך מן הפיסין ומן הזימיות.</p>","notation":["נ״ר"]},"44276":{"h":"פִּיסְעָא","r":"KRU15400","alt":[],"source":"krupnik","glosses":[{"text":"step","label":""}],"html":"<p>פסיעה, צעד step  תרג׳ ש״א כ׳ ג׳ (כפשע): כפיסעא חדא.</p>","notation":["נ׳"]},"44277":{"h":"פִּיסָק","r":"KRU15402","alt":[],"source":"krupnik","glosses":[{"text":"interruption","label":"1"},{"text":"slope","label":"2"}],"html":"<p>1 הפסקה interruption  ירוש׳ שקל׳ פ״ג מ״ז ע״ב: לשתותן בפיסק.\n2 מדרון slope  תוס׳ עיר׳ י׳ (ז), ב׳: ההרים והפיסקין וכו׳.</p>","notation":["ז׳"]},"44278":{"h":"פִּיסְקָא","r":"KRU15403","alt":[],"source":"krupnik","glosses":[{"text":"piece","label":"1"},{"text":"subscription for charity","label":"2"}],"html":"<p>1 חתיכה piece  ירוש׳ כלא׳ פ״ט ל״ב ע״ד: פיסקי דעמר.\n2 מגבית subscription for charity  דב״ר פ״ד: עשה שם ריש לקיש פיסקא.</p>","notation":["ז׳"]},"44279":{"h":"פִּיסְקוֹן","r":"KRU15404","alt":[],"source":"krupnik","glosses":[{"text":"surname of the angel Gabriel","label":""}],"html":"<p>כנוי למלאך גבריאל surname of the angel Gabriel  סנה׳ מ״ד ע״ב: שלש שמות יש לו פיסקון וכו׳.</p>","notation":[]},"44280":{"h":"פִּיסְקִינוֹס","r":"KRU15406","alt":[],"source":"krupnik","glosses":[{"text":"fish-pond","label":""}],"html":"<p>בריכה של דגים fish-pond  ילק׳ קהל׳ תתקס״ז: ברכות מים־פיסקנוס.</p>","notation":["ז׳"]},"44281":{"h":"פִּיסְקְתָא","r":"KRU15407","alt":[],"source":"krupnik","glosses":[{"text":"portion","label":""}],"html":"<p>חלק portion  ב״ב קנ״א ע״ב: פיסקתא דפרדיסא.</p>","notation":["נ׳"]},"44282":{"h":"פִּיסְתָא","r":"KRU15408","alt":[],"source":"krupnik","glosses":[{"text":"piece, bread","label":"1"}],"html":"<p>1 פת, לחם piece, bread  ירוש׳ תענ׳ פ״ד ס״ט ע״ג: הוה צבע פיסתיה בקטמא ואמר זו היא עיקר סעודת תשעה באב.\n2 עי׳ פִּיסָה. תרג׳ מל״א י״ח מ״ד (ככף איש): כפיסת יד גבר. </p>","notation":["נ׳"]},"44283":{"h":"פִּיסְתְּקָא","r":"KRU15409","alt":[],"source":"krupnik","glosses":[{"text":"pistachio-nut","label":""}],"html":"<p>מין אגוז pistachio-nut  גיט׳ נ״ט ע״א: כפיסתקא ופלגי דפיסתקא.</p>","notation":["ז׳"]},"44284":{"h":"פִּיעוּר","r":"KRU15410","alt":[],"source":"krupnik","glosses":[{"text":"uncovering oneself","label":""}],"html":"<p>גילוי בית הסתרים uncovering oneself  סנה׳ ק״ו ע״א: ומה איכפת לך כלום מבקשין ממך אלא פיעור.</p>","notation":["ז׳"]},"44285":{"h":"פִּיף","r":"KRU15411","alt":[],"source":"krupnik","glosses":[{"text":"knot","label":""}],"html":"<p>קשר knot  תוס׳ צוק׳ מקואות ז׳ (ח׳), י׳: וראשו מודבק בפיף או ביציאה.</p>","notation":["ז׳"]},"44286":{"h":"פֵּיפוּר","r":"KRU15413","alt":["פֵּיפוּרָא"],"source":"krupnik","glosses":[{"text":"trellis, wicker-work","label":""}],"html":"<p>שבכה, מקלעת trellis, wicker-work  ירוש׳ כלא׳ פ״ו ל׳ ע״ג: אם היה דרכו לפסע בין פיפור לפיפור; תרג׳ יב״ע דב׳ כ״ו ג׳: ותעטרון בסלייא וצוגיא ופיפורייא.</p>","notation":[]},"44287":{"h":"פִּיפְיוֹרָא","r":"KRU15416","alt":[],"source":"krupnik","glosses":[{"text":"a palace-guard","label":""}],"html":"<p>שומר הארמון a palace-guard  ע״ז י״א ע״א: ניפיורא נקט נורא קמי פיפיורא פיפיורא לדוכסא.</p>","notation":["ז׳"]},"44288":{"h":"פִּיפִילוֹן","r":"KRU15418","alt":[],"source":"krupnik","glosses":[{"text":"curtain","label":""}],"html":"<p>מסך curtain  ילק׳ תה׳ תשל״ה: נטל פיפילון ופירש עליו.</p>","notation":["ז׳"]},"44289":{"h":"פִּיפָנִי","r":"KRU15420","alt":[],"source":"krupnik","glosses":[{"text":"Epiphania, city in Syria","label":""}],"html":"<p>עיר בסוריא Epiphania, city in Syria  ב״ר פל״ז: החמתי – פיפני.</p>","notation":[]},"44290":{"h":"פִּיצוּלַיּיָא","r":"KRU15422","alt":[],"source":"krupnik","glosses":[{"text":"unripe fruits","label":""}],"html":"<p>פירות בוסר unripe fruits  ירוש׳ ביצה פ״ד ס״ב ע״ב וע״ג: באילין פיצולייא וכו׳.</p>","notation":["ז״ר"]},"44291":{"h":"פִּיצְטְלִין","r":"KRU15423","alt":[],"source":"krupnik","glosses":[{"text":"lozenges","label":""}],"html":"<p>מיני מתיקה lozenges  שמו״ר פמ״א: איני מבקש אלא מן הפיצטלין שבתוך פיך.</p>","notation":["ז״ר"]},"44292":{"h":"פִּיצְתָּא","r":"KRU15424","alt":[],"source":"krupnik","glosses":[{"text":"lot","label":""}],"html":"<p>גורל lot  תרג׳ יב״ע דב׳ ד׳ ל״ד (לקחת לו גוי מקרב גוי): למיפרשא ליה אומא בפיצתא.</p>","notation":["נ׳"]},"44293":{"h":"פִּיקָה","r":"KRU15426","alt":[],"source":"krupnik","glosses":[{"text":"protruding cartilage","label":"1"},{"text":"spinner's coil","label":"2"},{"text":"rise and fall","label":"3"}],"html":"<p>1 בליטה בגוף protruding cartilage  חול׳ פ״י מ״ד: פיקה של גרגרת.\n2 ראש הכישור spinner&#x27;s coil  כל׳ פי״א מ״ו: פיקה של מתכת.\n3 זעזוע rise and fall  ילק׳ אס׳ תתרנ״ד: מכניסין פיקה בממונו של עולם.</p>","notation":["נ׳"]},"44294":{"h":"פִּיקוּסָא","r":"KRU15429","alt":[],"source":"krupnik","glosses":[{"text":"removing the down (of plants)","label":""}],"html":"<p>הסרת השערות הדקות שבפרחים removing the down (of plants)  ב״מ פ״ח ע״ב: עד דגמר לפיקוסייהו.</p>","notation":["ז׳"]},"44295":{"h":"פִּיקְטְנִי","r":"KRU15431","alt":[],"source":"krupnik","glosses":[{"text":"a vessel","label":""}],"html":"<p>מין כלי a vessel  תוס׳ ב״ב ה׳ ד׳: המוכר בפיקטני וכו׳.</p>","notation":["נ׳"]},"44296":{"h":"פִּיקָס","r":"KRU15432","alt":[],"source":"krupnik","glosses":[{"text":"a red colour","label":"1"},{"text":"blossom","label":"2"}],"html":"<p>1 מין צבע אדום a red colour  ספרא טהר׳ מצורע נגעים פ״א: שני יכול פיקס ת״ל תולעת.\n2 פרח blossom  ב״מ פ״ח ע״ב: משינטל פיקס שלהן.</p>","notation":["ז׳"]},"44297":{"h":"פִּיקְעָא","r":"KRU15434","alt":[],"source":"krupnik","glosses":[{"text":"split","label":"1"},{"text":"slits in the rectum","label":"2"},{"text":"bitter-apple","label":"3"}],"html":"<p>1 בקיע split  ע״ז כ״ח ע״ב: ולינח פיקעא בהדי פיקעא.\n2 פי הטבעת slits in the rectum  שם: ר׳ יעקב חש בפיקעא.\n3 פקועה (מין קשוא) bitter-apple  תרג׳ מל״ב ד׳ ל״ט (פקועות שדה): פיקעי חקלא.</p>","notation":["ז׳"]},"44298":{"h":"פִּיקְפּוּק","r":"KRU15435","alt":[],"source":"krupnik","glosses":[{"text":"reproach","label":""}],"html":"<p>נזיפה reproach  ירוש׳ סנה׳ פ״ב ב׳ ע״ב: פיקפוקי דברים היו שם.</p>","notation":["ז׳"]},"44299":{"h":"פֵּיר","r":"KRU15437","alt":["פֵּירָא"],"source":"krupnik","glosses":[{"text":"pit","label":""}],"html":"<p>בור pit  כת׳ ע״ט ע״ב: פיר של גפרית; ב״ב י״א ע״א: פירא דסופלי.</p>","notation":[]},"44300":{"h":"פֵּירָא דְכַוְורֵי","r":"KRU15438","alt":[],"source":"krupnik","glosses":[{"text":"fish-pond","label":""}],"html":"<p>בריכה של דגים fish-pond  תענ׳ כ״ד ע״א: פירא דכוורי.</p>","notation":[]},"44301":{"h":"פֵּירָא","r":"KRU15439","alt":[],"source":"krupnik","glosses":[{"text":"fruit","label":"1"},{"text":"usufruct","label":"2"}],"html":"<p>1 פרי fruit  סוכה ל״א ע״ב: לא גמר פירא.\n2 תועלת, הנאה, שימוש usufruct  כת׳ ע״ט ע״א: פירא וכו׳ קרנא.</p>","notation":["ז׳"]},"44302":{"h":"פֵּירוּג","r":"KRU15440","alt":[],"source":"krupnik","glosses":[{"text":"exchange, price","label":""}],"html":"<p>מחיר, תמורה exchange, price  תרג׳ יב״ע דב׳ כ״ג י״ט: (מחיר כלב): פירוג דכלב.</p>","notation":["ז׳"]},"44303":{"h":"פִּירוֹז","r":"KRU15441","alt":[],"source":"krupnik","glosses":[{"text":"a man’s name","label":""}],"html":"<p>שם איש a man’s name  חול׳ ס״ב ע״ב: פירוז רשיעא.</p>","notation":[]},"44304":{"h":"פִּירוֹז אַנְדְרַפְתָּא","r":"KRU15442","alt":[],"source":"krupnik","glosses":[{"text":"a bird","label":""}],"html":"<p>מין עוף a bird  חול׳ ס״ב ע״ב: פירוז אנדרפתא אסיר וסימנך פירוז רשיעא.</p>","notation":[]},"44305":{"h":"פֵּירוּי","r":"KRU15443","alt":[],"source":"krupnik","glosses":[{"text":"fruitfulness","label":""}],"html":"<p>פריה, רביה fruitfulness  אסת״ר סוף: בהשפע בפירוי.</p>","notation":["ז׳"]},"44306":{"h":"פֵּירוּכָא","r":"KRU15444","alt":[],"source":"krupnik","glosses":[{"text":"grist","label":"1"},{"text":"sheaf","label":"2"}],"html":"<p>1 גריסין grist  תרג׳ יב״ע ויק׳ ב׳ ט״ז (גרש): מפירוכה.\n2 עומר, אלומה sheaf  תרג׳ יב״ע בר׳ ל״ז ז׳ (אלומות): פירכן.</p>","notation":["ז׳"]},"44307":{"h":"פֵּירוּק","r":"KRU15446","alt":[],"source":"krupnik","glosses":[{"text":"taking apart","label":""}],"html":"<p>הפרדת כלי או בנין מורכב taking apart  במ״ר פ״ד: פירוקן בשעת מסעות כעמידתן בשעת חניית מסעות.</p>","notation":["ז׳"]},"44308":{"h":"פֵּירוּקָא","r":"KRU15447","alt":[],"source":"krupnik","glosses":[{"text":"reply, solution","label":""}],"html":"<p>תירוץ reply, solution  ב״ק קי״ז ע״א: האי קושיא והאי קושיא האי פירוקא והאי פירוקא.</p>","notation":["ז׳"]},"44309":{"h":"פֵּירוּר","r":"KRU15448","alt":[],"source":"krupnik","glosses":[{"text":"crumbling","label":"1"},{"text":"crumb","label":"2"}],"html":"<p>1 מלילת לחם לפתותים crumbling  פס׳ כ״ח ע״א: חמץ וכו׳ בעי פירור.\n2 פתותים crumb  ירוש׳ מו״ק פ״ב פ״א ע״ב: הוה מלקט פירורין ואכל.</p>","notation":["ז׳"]},"44310":{"h":"פֵּירוּשׁ","r":"KRU15449","alt":["פֵּירוּשָׁא"],"source":"krupnik","glosses":[{"text":"explanation, commentary","label":""},{"text":"explicitly","label":""}],"html":"<p>ביאור, הסבר explanation, commentary  ב״ב נ״ב ע״א: וכולן שאמרו בשעת מיתתו של פלוני הן יעשה בפירושן ואם לאו יעשה פירוש לפירושן; ע״ז ד׳ ע״א: לא ידע למימר לן פירושא דהאי פסוקא. בְּפֵירוּשׁ תה״פ בפה מלא, בהדיא, בבירור explicitly  חול׳ צ״ה ע״א: לאו בפירוש איתמר אלא מכללא איתמר. </p>","notation":[]},"44311":{"h":"פִּירְזוּמָא","r":"KRU15452","alt":[],"source":"krupnik","glosses":[{"text":"juice","label":""}],"html":"<p>עסיס juice  פס׳ ק״ז ע״א: ומה פירזומא וכו׳ שיכרא מיבעיא.</p>","notation":["ז׳"]},"44312":{"h":"פירזומטא","r":"KRU15453","alt":[],"source":"krupnik","glosses":[{"text":"aprons","label":""}],"html":"<p> aprons  ירוש׳ שבת פ״ו ח׳ ע״ב: המחלצות – פירזומטא.</p>","notation":["ז״ר","Source emendation: פְּרִיזוֹמָטָא"]},"44313":{"h":"פִּירְחָא","r":"KRU15454","alt":[],"source":"krupnik","glosses":[{"text":"palpitation of the heart","label":""}],"html":"<p>דפיקת הלב palpitation of the heart  גיט׳ ס״ט ע״ב: לפירחא דליבא ליתי וכו׳.</p>","notation":["ז׳"]},"44314":{"h":"פִּירָט","r":"KRU15455","alt":[],"source":"krupnik","glosses":[{"text":"pirate","label":""}],"html":"<p>שודד הים pirate  שמו״ר פי״ז: ספינות של פירטין.</p>","notation":["ז׳"]},"44315":{"h":"פִּירְכָא","r":"KRU15456","alt":[],"source":"krupnik","glosses":[{"text":"refutation, objection","label":""}],"html":"<p>קושיא, טענה, סתירה refutation, objection  חול׳ ע״ו ע״ב: אהדורי אפירכי למה לך.</p>","notation":["ז׳"]},"44316":{"h":"פִּירְכּוּס","r":"KRU15457","alt":[],"source":"krupnik","glosses":[{"text":"painting, dyeing the hair","label":"1"},{"text":"spasmodic movement","label":"2"}],"html":"<p>1 קישוט בצבעים וכדומה painting, dyeing the hair  ב״מ ס׳ ע״ב: פירכוס באדם מה היא כי הא דעבדא סבא דאזל צבעיה לרישיה ולדיקניה.\n2 פרפור spasmodic movement  חול׳ ל״ח ע״א: פירכוס שאמרו בסוף שחיטה.</p>","notation":["ז׳"]},"44317":{"h":"פירכורין","r":"KRU15459","alt":[],"source":"krupnik","glosses":[{"text":"district","label":""}],"html":"<p>גליל, סביבה district  דב״ר פי״א: אתה נפגשת עם המלאך בפירכורין שלך. </p>","notation":["ז׳","Source emendation: פְּרִיכוֹרִין"]},"44318":{"h":"פִּירְמָא","r":"KRU15460","alt":[],"source":"krupnik","glosses":[{"text":"hash","label":""}],"html":"<p>מאכל כתות hash  גיט׳ ס״ט ע״ב: פירמא דסילקא וכו׳ פירמא דכרתי.</p>","notation":["ז׳"]},"44319":{"h":"פִּירְצָא","r":"KRU15462","alt":[],"source":"krupnik","glosses":[{"text":"hole","label":""}],"html":"<p>נקב hole  שבת ק״ה ע״א: כיון דאית ביה פירצי פירצי.</p>","notation":["ז׳"]},"44320":{"h":"פִּירְקָא","r":"KRU15463","alt":[],"source":"krupnik","glosses":[{"text":"chapter","label":"1"},{"text":"lesson","label":"2"},{"text":"time","label":"3"},{"text":"puberty","label":"4"}],"html":"<p>1 פרק, פרשה chapter  פס׳ קי״ז ע״א: סוף פירקא ריש פירקא וכו׳.\n2 דרשה, הרצאה lesson  פס׳ ק׳ ע״א: אנא איקלעי לפירקיה דר׳ פנחס.\n3 זמן time תרג׳ יב״ע במ׳ כ״ב ד׳: למהוי מלכין לפירקין.\n4 בגרות puberty  תרג׳ יב״ע ויק׳ י״ט כ׳: סמוך לפירקיהון.</p>","notation":[]},"44321":{"h":"פֵּירָקוֹן","r":"KRU15464","alt":[],"source":"krupnik","glosses":[{"text":"redemption","label":""}],"html":"<p>פדיון redemption  כת׳ מ״ז ע״ב: מזונותיה וכו׳ ופירקונה.</p>","notation":["ז׳"]},"44322":{"h":"פִּירְקְתָא","r":"KRU15466","alt":[],"source":"krupnik","glosses":[{"text":"joint","label":""}],"html":"<p>פרק וקשר שבין חוליה לחוליה באברים joint  תרג׳ איכה ה׳ ה׳: פירקת צוורנא.</p>","notation":["נ׳"]},"44323":{"h":"פִּירְשָׁה","r":"KRU15467","alt":[],"source":"krupnik","glosses":[{"text":"secrection, excrement","label":""}],"html":"<p>פרש, צואה secrection, excrement  חול׳ קט״ז ע״ב: פירשא בעלמא הוא.</p>","notation":["ז׳"]},"44324":{"h":"פִּישׁוּט","r":"KRU15468","alt":[],"source":"krupnik","glosses":[{"text":"stretching forth","label":""}],"html":"<p>הושטה stretching forth  מגי׳ כ״ב ע״ב: פישוט ידים ורגלים.</p>","notation":["ז׳"]},"44325":{"h":"פִּישְׁפָּשׁ","r":"KRU15469","alt":[],"source":"krupnik","glosses":[{"text":"wicket","label":""}],"html":"<p>פתח קטן בשער wicket  זבח׳ נ״ו ע״א: שני פישפשין היו בבית החליפות גובהן שמונה וכו׳. ועי׳ פִּשְׁפָּשׁ.</p>","notation":["ז׳"]},"44326":{"h":"פִּישְׁפָּשָׁה","r":"KRU15470","alt":[],"source":"krupnik","glosses":[{"text":"name of an Amora","label":""}],"html":"<p>שם אמורא name of an Amora  ירוש׳ שבי׳ פ״ו ל״ו ע״ג: פישפשה אמר קומי ר׳ יוסי.</p>","notation":[]},"44327":{"h":"פִּישְׁרָא","r":"KRU15471","alt":[],"source":"krupnik","glosses":[{"text":"solution","label":"1"},{"text":"cud","label":"2"},{"text":"thawing snow","label":"3"}],"html":"<p>1 פתרון solution  תרג׳ שופ׳ ז׳ ט״ו (שברו): פישריה.\n2 גרה שהבהמה מעלה cud  תרג׳ ויק׳ י״א ג׳ (מעלה גרה): מסקא פישרא.\n3 שלג נמס thawing snow  תרג׳ שנ׳ אס׳ ג׳ ח׳: פישרי דטבת.</p>","notation":["ז׳"]},"44328":{"h":"פִּיתָּא","r":"KRU15472","alt":[],"source":"krupnik","glosses":[{"text":"bread","label":""}],"html":"<p>לחם לחם, פת bread  בר׳ מ׳ ע״ב: בריך רחמנא מריה דהאי פיתא.</p>","notation":["ז׳"]},"44329":{"h":"פִּיתּוּי","r":"KRU15473","alt":[],"source":"krupnik","glosses":[{"text":"persuasion, seduction","label":"1"},{"text":"claims of the seduced","label":"2"}],"html":"<p>1 הסתה והדחה persuasion, seduction  שמ״ר פ״ג: בתחלה פיתוי פיתיתי אותך מכאן ואילך אמת אני מדבר עמך.\n2 תביעת נערה מפותה claims of the seduced  כת׳ ל״ה ע״ב: אין לה לא אונס ולא פיתוי.</p>","notation":["ז׳"]},"44330":{"h":"פִּיתּוּלָא","r":"KRU15474","alt":[],"source":"krupnik","glosses":[{"text":"perverseness","label":""}],"html":"<p>הפכפכנות perverseness  תרג׳ מש׳ ח׳ (נפתל ועקש): פיתולא ועיקומא.</p>","notation":["ז׳"]},"44331":{"h":"פִּיתוֹם","r":"KRU15475","alt":[],"source":"krupnik","glosses":[{"text":"ventriloquist","label":""}],"html":"<p>בעל אוב ventriloquist  סנה׳ פ״ז מ״ז: בעל אוב זה פיתום המדבר משחיו.</p>","notation":["ז׳"]},"44332":{"h":"פִּיתוּנָא","r":"KRU15476","alt":[],"source":"krupnik","glosses":[{"text":"adder","label":""}],"html":"<p>פתן adder  תרג׳ יב״ע דב׳ ל״ב ל״ג (פתנים): פיתוניא.</p>","notation":["ז׳"]},"44333":{"h":"פִּיתֵּחַ","r":"KRU15479","alt":[],"source":"krupnik","glosses":[{"text":"seeing","label":""}],"html":"<p>פקח, גלוי עינים seeing  ב״ב קכ״ח ע״א: פיתח ונסתמא וחזר ונתפתח.</p>","notation":["ז׳"]},"44334":{"h":"פִּיתְחָא","r":"KRU15480","alt":[],"source":"krupnik","glosses":[{"text":"opening, door","label":""}],"html":"<p>פתח opening, door  סנה׳ ק״י ע״א: לקרובי פיתחא.</p>","notation":["ז׳"]},"44335":{"h":"פִּיתְנָא","r":"KRU15482","alt":[],"source":"krupnik","glosses":[{"text":"adder","label":""}],"html":"<p>פתן adder  תרג׳ בר׳ מ״ט י״ז (שפיפון עלי ארח): וכפיתנא יכמון על שבילא.</p>","notation":["ז׳"]},"44336":{"h":"פִּיתָּק","r":"KRU15483","alt":["פִּיתְקָא"],"source":"krupnik","glosses":[{"text":"ballot; lot, decree","label":""}],"html":"<p>מכתב קטן, לוח; גורל ballot; lot, decree  ירוש׳ סוטה פ״א י״ז ע״ב: כתוב הד פיתק; בכורים פ״ג ס״ה ע״ד: אוף ר׳ יונה הוה בפיתקא; סוטה י״ב ע״א: לא היו בפיתקה של חוה.</p>","notation":[]},"44337":{"h":"פִּיתְרָא","r":"KRU15484","alt":[],"source":"krupnik","glosses":[{"text":"interpretation","label":"1"},{"text":"a wine vessel","label":"2"}],"html":"<p>1 פשר דבר interpretation  ירוש׳ דמ׳ פ״ז כ״ו ע״ג: אין לך אלא כהדין פיתרא קדמיא.\n2 כד a wine vessel  ירוש׳ ע״ז פ״ב מ״א ע״ג: באילין פיתרייא רברבייא.</p>","notation":["ז׳"]},"44338":{"h":"פִּיתְּתָא","r":"KRU15485","alt":[],"source":"krupnik","glosses":[{"text":"piece","label":""}],"html":"<p>פרוסה piece  תרג׳ מש׳ ב״ח כ״א (פת לחם): פיתתא דלחמא.</p>","notation":["נ׳"]},"44339":{"h":"פָּכוֹרָה","r":"KRU15486","alt":[],"source":"krupnik","glosses":[{"text":"a man’s name","label":""}],"html":"<p>a man’s name  ירוש׳ סוטה פ״ט כ״ד ע״א: יהודה בן פכורה. </p>","notation":["שם איש"]},"44340":{"h":"פִּכֵּחַ","r":"KRU15487","alt":[],"source":"krupnik","glosses":[{"text":"to make evaporate","label":"פיעל,"}],"html":"<p>פיעל, הפיג to make evaporate  ב״ב י׳ ע״א: יין קשה שינה מפכחתו.</p>","notation":[]},"44341":{"h":"פַּכְחוּתָא","r":"KRU15489","alt":[],"source":"krupnik","glosses":[{"text":"fluid","label":""}],"html":"<p>חומר נוזל fluid  נדה כ׳ ע״א: פכחותא דדיותא.</p>","notation":["נ׳"]},"44342":{"h":"פַּכְסְמִין","r":"KRU15490","alt":[],"source":"krupnik","glosses":[{"text":"biscuits","label":""}],"html":"<p>צנימים biscuits  במ״ר פ״ז: ואוכלין פכסמין.</p>","notation":["ז״ר"]},"44343":{"h":"פַּכְסַס","r":"KRU15491","alt":[],"source":"krupnik","glosses":[{"text":"a man’s name","label":""}],"html":"<p>a man’s name  ירוש׳ נזיר פ״ז נ״ה ע״ד: יוסי בן פכסס. </p>","notation":["שם איש"]},"44344":{"h":"פִּכְפֵּךְ","r":"KRU15492","alt":[],"source":"krupnik","glosses":[{"text":"to drip","label":""}],"html":"<p>טפטף to drip  תוס׳ צוק׳ סוכה ג׳: שמפכפכין ועולין וכו׳.</p>","notation":["פ״ע"]},"44345":{"h":"פָּכַר","r":"KRU15493","alt":[],"source":"krupnik","glosses":[{"text":"to break","label":""}],"html":"<p>שבר to break  ב״ר פכ״ג: לשני אילנות שהיו סמוכין זה לזה פכרה רוח את אחד מהן וכו׳.</p>","notation":["פ״י"]},"44346":{"h":"פְּכַר","r":"KRU15494","alt":[],"source":"krupnik","glosses":[{"text":"to clasp one’s hands","label":""}],"html":"<p>שילב, חיבק את ידיו to clasp one’s hands  שבת י׳ ע״א: פכר ידיה ומצלי.</p>","notation":["פ״י"]},"44347":{"h":"פַּכֵּר","r":"KRU15495","alt":[],"source":"krupnik","glosses":[{"text":"to demolish","label":""},{"text":"to be demolished","label":""}],"html":"<p>הרס to demolish  תרג׳ יב״ע ויק׳ י״ד מ״ה (ונתץ את הבית): ויפכרון ית ביתא. אִתְפְּכַר אתפ׳, נהרס to be demolished  תרג׳ יב״ע בר׳ כ״ב ט׳: אתפכר במוי דטובענא. </p>","notation":["פַעל"]},"44348":{"h":"פַּלָּאטינֵי","r":"KRU15497","alt":[],"source":"krupnik","glosses":[{"text":"palace-guard","label":""}],"html":"<p>פקידי חצר המלכות palace-guard  במ״ר פ״ה: אעפ״י שהיתה משפחת קרח פלאטיני וכו׳.</p>","notation":["ז״ר"]},"44349":{"h":"פִּלְבֵּל","r":"KRU15498","alt":[],"source":"krupnik","glosses":[{"text":"to roll","label":""}],"html":"<p>סיבב וגלגל to roll  תנח׳ בובר חוקת ג׳: עיניה מפלבלות.</p>","notation":["פ״ע"]},"44350":{"h":"פלג","r":"KRU15499","alt":[],"source":"krupnik","glosses":[{"text":"to go away","label":"הִפְלִיג הפ׳, 1"},{"text":"to go to sea","label":"הִפְלִיג הפ׳, 2"},{"text":"to rest from work","label":"הִפְלִיג הפ׳, 3"},{"text":"to divert, to put off","label":"הִפְלִיג הפ׳, 4"},{"text":"to be divided","label":"הִתְפַּלֵג התפ׳,"}],"html":"<p>הִפְלִיג הפ׳, 1 נתרחק to go away  ירוש׳ בר׳ פ״א ב׳ ע״ד: יצא המלך לידע מה הוא מבקש ומצאו שהפליג.\nהִפְלִיג הפ׳, 2 נסע בספינה to go to sea  שבת י״ט ע״א: אין מפליגין בספינה.\nהִפְלִיג הפ׳, 3 שבת to rest from work  ויק״ר פ״ל: לכשיפליג ממלאכתו.\nהִפְלִיג הפ׳, 4 דחה, הסיח את הדעת to divert, to put off  ירוש׳ ע״ז פ״ב מ׳ ע״ג: אם שואלו להיכן הוא הולך יפליגנו כשם שהפליג יעקב אבינו לעשו.\nהִתְפַּלֵג התפ׳, נתחלק to be divided  ב״ר פט״ו: וכל מימי בראשית מתפלגין מתחתיו.</p>","notation":["Source marks no qal form"]},"44351":{"h":"פְּלֵג","r":"KRU15500","alt":["פְּלֵיג"],"source":"krupnik","glosses":[{"text":"to divide","label":"1"},{"text":"to differ","label":"2"}],"html":"<p>1 חילק to divide  תרג׳ שמ׳ כ״א ל״ה (וחצו את כספו): ויפלגין ית כספיה.\n2 היה מחולק בדעות to differ  חול׳ צ״ב ע״ב: מיפלג פליגי ביה.</p>","notation":[]},"44352":{"h":"פְּלַג אִיקַר","r":"KRU15501","alt":["פְּלַג יִקְרָא"],"source":"krupnik","glosses":[{"text":"to do honour","label":""}],"html":"<p>חילק כבוד to do honour  ב״ב קי״ט ע״ב: פליג ליה רביה יקרא; ירוש׳ תענ׳ פ״ד ס״ח ע״א: פלגון איקר לשמואל.</p>","notation":[]},"44353":{"h":"פַּלֵּג","r":"KRU15502","alt":[],"source":"krupnik","glosses":[{"text":"to be divided","label":"אִתְפַּלֵּג, אִיפַּלֵּג אתפ׳, 1"},{"text":"to differ","label":"אִתְפַּלֵּג, אִיפַּלֵּג אתפ׳, 2"},{"text":"to be distinguished","label":"אִתְפַּלֵּג, אִיפַּלֵּג אתפ׳, 3"}],"html":"<p>פַעל, אַפְלֵג אפ׳, כנ״ל 1. תרג׳ בר׳ ט״ו י׳ (ויבתר אותם בתוך): ופליג יתהון בשוי; יב״ע שם מ״ט ז׳ (אחלקם): אפליג אחסנא. \nאִתְפַּלֵּג, אִיפַּלֵּג אתפ׳, 1 נחלק to be divided  תרג׳ איוב ל״ח כ״ד (יחלק אור): יתפליג נהורא; ב״ב קכ״א ע״ב: ארץ ישראל לשבטים איפלוג וכו׳.\nאִתְפַּלֵּג, אִיפַּלֵּג אתפ׳, 2 היה מחולק בדעות to differ  ב״ר פכ״א: אתפלגון ר׳ אדא בר אהבה ור׳ המנונא.\nאִתְפַּלֵּג, אִיפַּלֵּג אתפ׳, 3 הצטיין to be distinguished  גיט׳ כ״ח ע״א: כיון דאיפליג איפליג.</p>","notation":[]},"44354":{"h":"פֶּלֶג","r":"KRU15503","alt":[],"source":"krupnik","glosses":[{"text":"share","label":""}],"html":"<p>חלק share  תנח׳ משפ׳ ז׳: כל המוכיח את חבירו לשם שמים זוכה לפלגו של הקב״ה.</p>","notation":["Marked biblical in source"]},"44355":{"h":"פְּלַג","r":"KRU15504","alt":["פַּלְגָּא"],"source":"krupnik","glosses":[{"text":"half","label":""}],"html":"<p>מחצית half  בר׳ פ״ד מ״א: עד פלג המנחה; שבת פ״ט ע״ב: פלגא עלי ופלגא עלך.</p>","notation":[]},"44356":{"h":"פַּלְגָא קֵיסָר","r":"KRU15505","alt":[],"source":"krupnik","glosses":[{"text":"Vice-Caesar","label":""}],"html":"<p>שני למלך Vice-Caesar  סנה׳ צ״ח ע״ב: קיסר ופלגא קיסר.</p>","notation":[]},"44357":{"h":"פַּלָּגָּא","r":"KRU15506","alt":["פַּלְגָּאָה"],"source":"krupnik","glosses":[{"text":"querulous man","label":""}],"html":"<p>איש ריב querulous man  קיד׳ נ״ח ע״א: פלגא אוקמינכי; גיט׳ ל״א ע״ב: מקמי פלגאה ניקום?</p>","notation":[]},"44358":{"h":"פַּלְגְּלִיסָא","r":"KRU15509","alt":[],"source":"krupnik","glosses":[{"text":"target for projectiles","label":""}],"html":"<p>מטרה לחץ target for projectiles  תרג׳ איכה ג׳ י״ב (כמטרא לחץ): כפלגליסא לגירא.</p>","notation":["ז׳"]},"44359":{"h":"פַּלְגַּס","r":"KRU15510","alt":[],"source":"krupnik","glosses":[{"text":"an animal of beginning maturity","label":""}],"html":"<p>בעל חי בתחלת ימי בגרותו an animal of beginning maturity  פרה פ״א מ״ג: בן שלשה עשר חודש אינו כשר לא לאיל ולא לכבש ר׳ טרפון קורהו פלגס.</p>","notation":["ז׳"]},"44360":{"h":"פלגס","r":"KRU15511","alt":[],"source":"krupnik","glosses":[{"text":"a cloak","label":""}],"html":"<p>מין בגד a cloak  ירוש׳ תענ׳ פ״ד ס״ט ע״א: אורגי פלגס.</p>","notation":["ז׳","Source emendation: פִּינוֹלֵס"]},"44361":{"h":"פּלדוס","r":"KRU15513","alt":["פַּלְדֵּיס","פִּלְדֵּס"],"source":"krupnik","glosses":[{"text":"a cloak","label":""}],"html":"<p>מין שמלה, סדין a cloak  תוס׳ צוק׳ מגי׳ ד׳ (ג׳), ג׳: עטוף וכו׳ בפלדוס; תרג׳ שופ׳ י״ד י״ב (סדינים): פלדסין; דחי״ב ט׳ כ״ד (ושלמות): פלדיסין דבוץ.</p>","notation":[]},"44362":{"h":"פָּלָה","r":"KRU15514","alt":[],"source":"krupnik","glosses":[{"text":"to search","label":"פיעל,"}],"html":"<p>פיעל, פִּלָּה בדק to search  שבת י״ב ע״א: אין פולין לאור הנר; שם פ״א מ״ג: לא יפלה את כליו.</p>","notation":[]},"44363":{"h":"פְּלוּג","r":"KRU15516","alt":[],"source":"krupnik","glosses":[{"text":"portion","label":""}],"html":"<p>מנה (בסעודה) portion  מגי׳ ז׳ ע״ב: אכלי בהו שיתין פלוגי.</p>","notation":["ז׳"]},"44364":{"h":"פְּלוּגָה","r":"KRU15517","alt":[],"source":"krupnik","glosses":[{"text":"dispute","label":""}],"html":"<p>פְּלוּגַת דְּבָרִים מחלוקת dispute  שהש״ר ח׳ י״ג: לפי שאין ביניהן איבה וקנאה וכו׳ ופלוגת דברים.</p>","notation":["Marked biblical in source"]},"44365":{"h":"פְּלוּגְתָּא","r":"KRU15518","alt":[],"source":"krupnik","glosses":[{"text":"division","label":"1"},{"text":"difference of opinion, contest","label":"2"},{"text":"difference","label":"3"},{"text":"name of a place","label":"4"}],"html":"<p>1 מחלקה division  תרג׳ דהי״ב כ״ג ח׳ (המחלקות): פלוגוותא.\n2 וכוח, מחלוקת difference of opinion, contest  יומא ד׳ ע״ב: במאי קא מיפלגי וכו׳ בפלוגתא דהני תנאי.\n3 הבדל difference  מו״ק י״ד ע״ג: אית ביה פלוגתא.\n4 שם מקום name of a place  במ״ר ס״ט: הדה בית מעון שיורדים לה מפלוגתא.</p>","notation":["נ׳"]},"44366":{"h":"פְּלוּלִינַיָּא","r":"KRU15522","alt":[],"source":"krupnik","glosses":[{"text":"a herb","label":""}],"html":"<p>מין ירק a herb  ירוש׳ פס׳ פ״ג ל׳ ע״א: הורי ר׳ יוסי באילין פלוליניא וכו׳.</p>","notation":["ז״ר"]},"44367":{"h":"פְּלוּמָא","r":"KRU15523","alt":[],"source":"krupnik","glosses":[{"text":"down-pillow","label":""}],"html":"<p>כר של נוצה דקה down-pillow  שהש״ר א׳ י״ז: אבנים שישן עליהם יעקב אבינו נעשו כמטה וכפלומא.</p>","notation":["נ׳"]},"44368":{"h":"פלומופילון","r":"KRU15524","alt":[],"source":"krupnik","glosses":[{"text":"primipilate","label":""}],"html":"<p>ראש הפקידים primipilate  ספרי במ׳ קל״א: שימש פלומופילון שלו.</p>","notation":["ז׳","Source emendation: פְּרִימוֹפִילוֹן"]},"44369":{"h":"פְּלוּמַטְרִין","r":"KRU15525","alt":[],"source":"krupnik","glosses":[{"text":"chest, box","label":""}],"html":"<p>תיבה לשמירת דברי חפץ chest, box  פסיק״ר פ״ו: היה לו פלומטרין אחד של זהב קטן והיה כל שעה נוטלו ומונה אותו.</p>","notation":["ז׳"]},"44370":{"h":"פְּלוֹנִיקְיָא","r":"KRU15526","alt":[],"source":"krupnik","glosses":[{"text":"quarrel","label":""}],"html":"<p>ריב quarrel  תנח׳ וארא י״א: שמא פלוניקיא יש למעלה.</p>","notation":["נ׳"]},"44371":{"h":"פלונס","r":"KRU15527","alt":[],"source":"krupnik","glosses":[{"text":"a cloak","label":""}],"html":"<p>מין בגד a cloak  ירוש׳ נד׳ פ״י מ״ב ע״ב: מהו להתיר בפלונס.</p>","notation":["ז׳","Source emendation: פִּינוֹלֵס"]},"44372":{"h":"פְּלוֹסלוֹס","r":"KRU15529","alt":[],"source":"krupnik","glosses":[{"text":"a man’s name","label":"2"}],"html":"<p>1 עי׳ פְּלַסְלוֹס. ירוש׳ כלא׳ פ״א כ״ז ע״א: התורמוס והפלוסלוס וכו׳. \n2 שם איש a man’s name  ירוש׳ ע״ז פ״ג מ״ד: פרקלוס בן פלוסלוס.</p>","notation":["ז׳"]},"44373":{"h":"פָּלַח","r":"KRU15532","alt":[],"source":"krupnik","glosses":[{"text":"to worship","label":""}],"html":"<p>העריץ ועבד לאלהות to worship  תוס׳ ע״ז א׳ ה׳: אינו אסור אלא לפולחין בלבד.</p>","notation":["Marked biblical in source"]},"44374":{"h":"פְּלַח","r":"KRU15533","alt":[],"source":"krupnik","glosses":[{"text":"to work","label":"1"},{"text":"to worship","label":"2"}],"html":"<p>1 עבד to work  תרג׳ שמ׳ כ׳ ט׳ (ששת ימים תעבוד): שיתא יומין תפלח.\n2 עבד לאלהות to worship  סנה׳ ק״ב ע״ב: מאי טעמא פלחת לעבודה זרה.</p>","notation":["פ״י"]},"44375":{"h":"פַּלַּח","r":"KRU15534","alt":[],"source":"krupnik","glosses":[{"text":"to work","label":""},{"text":"to make work","label":""},{"text":"to be tilled","label":""}],"html":"<p>עשה, פעל to work  תרג׳ יש׳ ל״ב ז׳ (מעשה הצדקה): מפלחי צדקתא. אַפְלַח  אפ׳, העביד to make work  תרג׳ דהי״ב ב׳ י״ז (להעביד את העם): לאפלחא ית עמא. אִתְפְּלַח אתפ׳, נעבד to be tilled  תרג׳ דב׳ כ״א ד׳ (נחל איתן אשר לא יעבד בו): נחל בייר דלא יתפלח ביה. </p>","notation":["פַעל"]},"44376":{"h":"פָּלְחָא","r":"KRU15535","alt":[],"source":"krupnik","glosses":[{"text":"heathen","label":""}],"html":"<p>עובד עבודה זרה heathen  תרג׳ יב״ע ויק׳ כ״ה מ״ז (לעקר משפחת גר): ולפלחהא דמזרעית גיורא.</p>","notation":["ז׳"]},"44377":{"h":"פָּלַט","r":"KRU15536","alt":[],"source":"krupnik","glosses":[{"text":"to vomit, to give out","label":""},{"text":"to tear off","label":""},{"text":"to be saved","label":""}],"html":"<p>1) הקיא, הוציא מתוכו to vomit, to give out  ausspeien פס׳ ע״ד ע״ב: כבולעו כך פולטו. 2) קרע to tear off  חול׳ קכ״א ע״א: בשר שפלטתו סכין. הִתְפַּלֵּט התפ׳, נמלט וניצל to be saved  תנח׳ שמות י״ז: עתיד היה המבול לבוא לעולם ויתפלט ממנו נח ובניו. </p>","notation":[]},"44378":{"h":"פַּלְטָא","r":"KRU15537","alt":[],"source":"krupnik","glosses":[{"text":"a man’s name","label":""}],"html":"<p>a man’s name  ירוש׳ תר׳ פ״י מ״ז ע״ב: לוי בר פלטא. </p>","notation":["שם איש"]},"44379":{"h":"פַּלְטוֹרָא","r":"KRU15538","alt":[],"source":"krupnik","glosses":[{"text":"market officer","label":""}],"html":"<p>משגיח השוק market officer  תרג׳ יח׳ כ״ג מ׳: אתקינת שוקין ומנית פלטורין.</p>","notation":["ז׳"]},"44380":{"h":"פַּלְטוֹרָה","r":"KRU15539","alt":["פַּלְטוֹרִי"],"source":"krupnik","glosses":[{"text":"palace","label":""}],"html":"<p>ארמון palace  ספרי דב׳ ש״ט: מי שהכניסו אביו עשר פלטוריות ועמד וקנה פלטורה אחת משלו ואותה היה אוהב מכל פלטורין שהנחילו אביו.</p>","notation":[]},"44381":{"h":"פְּלַטְיָא","r":"KRU15540","alt":[],"source":"krupnik","glosses":[{"text":"street","label":""}],"html":"<p>רחוב street  ב״ר פכ״ב: אין יצר הרע מהלך לצדדים אלא באמצע פלטיא.</p>","notation":["נ׳"]},"44382":{"h":"פַּלָּטְיָאנֵי","r":"KRU15541","alt":[],"source":"krupnik","glosses":[{"text":"noblemen","label":""}],"html":"<p>בני מרום עם הארץ noblemen  ויק״ר פ״ב: אפרים–פלטיאני.</p>","notation":["ז״ר"]},"44383":{"h":"פְּלַטְיוֹן","r":"KRU15543","alt":[],"source":"krupnik","glosses":[{"text":"a man’s name","label":""}],"html":"<p>a man’s name  שהש״ר ו׳ י׳: פלטיון איש רומי. </p>","notation":["שם איש"]},"44384":{"h":"פְּלַטְיוּתָא","r":"KRU15544","alt":[],"source":"krupnik","glosses":[{"text":"plenty","label":"2"}],"html":"<p>1 פְּלַטְיָא. ירוש׳ בר׳ פ״ג ו׳ ע״א: פלטיותא דציפורי. \n2 שפע plenty  תרג׳ איוב ל״ז י׳ (ורוחב מים): פלטיות מיא.</p>","notation":["נ׳"]},"44385":{"h":"פַּלָּטִינִין","r":"KRU15547","alt":[],"source":"krupnik","glosses":[{"text":"palace-guards","label":""}],"html":"<p>פקידי הארמון palace-guards  במ״ר פ״א: שבטו של לוי פלטינין היו.</p>","notation":["ז״ר"]},"44386":{"h":"פַּלְטֵיר","r":"KRU15548","alt":[],"source":"krupnik","glosses":[{"text":"palace","label":""}],"html":"<p>ארמון palace  אסת״ר א׳ ב׳: שני פלטירין אחד לקיץ ואחד לחורף.</p>","notation":["ז׳"]},"44387":{"h":"פַּלְטֵירָא","r":"KRU15549","alt":[],"source":"krupnik","glosses":[{"text":"bakery-shop","label":""}],"html":"<p>חנות האופה bakery-shop  ב״ר פב״ב: אזל ויתיב קמי פלטירא.</p>","notation":["ז׳"]},"44388":{"h":"פַּלְטֵירָה","r":"KRU15550","alt":[],"source":"krupnik","glosses":[{"text":"goods for sale","label":"2"}],"html":"<p>1 עי׳ פְּלַטְיָא. ב״ר פס״ט: מה פלטירה זו מבלה את העוברים והשבים והיא קיימת לעולם. \n2 סחורה goods for sale ירוש׳ ב״ק פ״ב ג׳ ע״א: אפיק פלטירה.</p>","notation":["נ׳"]},"44389":{"h":"פַּלְטֵר","r":"KRU15552","alt":[],"source":"krupnik","glosses":[{"text":"palace","label":"1"},{"text":"seller of baker's ware","label":"2"},{"text":"bakery-shop","label":"3"}],"html":"<p>1 ארמון palace  במ״ר פי״ג: יכנס המלך לפלטרו.\n2 מוכר מיני מאפה seller of baker&#x27;s ware  ע״ז פ״ד מ״ט: מוליכין עמו פת לפלטר.\n3 חנות האופה bakery-shop  ירוש׳ דמ׳ פ״ב כ״ג ע״א: אם היה מוכר בפלטר או בחנות הסמוכה לפלטר.</p>","notation":["ז׳"]},"44390":{"h":"פַּלְטְרִין","r":"KRU15554","alt":[],"source":"krupnik","glosses":[{"text":"palace","label":""}],"html":"<p>ארמון palace  סנה׳ פ״ב מ״ג: אינו יוצא מפתח פלטרין שלו.</p>","notation":["ז׳"]},"44391":{"h":"פְּלַטְתָה","r":"KRU15555","alt":[],"source":"krupnik","glosses":[{"text":"name of a place","label":""}],"html":"<p>name of a place  ירוש׳ סוטה פ״א י״ז ע״א: הדא בית מעיין שיורדין בה מפלטתה ועולין בה מטיבריה. </p>","notation":["שם מקום"]},"44392":{"h":"פְּלֵי","r":"KRU15556","alt":[],"source":"krupnik","glosses":[{"text":"to split","label":""}],"html":"<p>בקע to split  יומא פ״ה ע״א: בהדי דקא פלי רישיה.</p>","notation":["פ״י"]},"44393":{"h":"פַּלֵּי","r":"KRU15557","alt":[],"source":"krupnik","glosses":[{"text":"to sneer at","label":""}],"html":"<p>עי׳ פָּלָה. ירוש׳ מו״ק פ״ג פ״ב ע״א: מסלי מאנוי. אַפְלֵי  אפ׳, לגלג to sneer at  איכ״ר א׳ א׳ (חד מאתינס ח׳): מכאן ולהבא לא תפלי בבני ירושלם. </p>","notation":["פַעל"]},"44394":{"h":"פַּלְיָא בֵיאָרִי","r":"KRU15558","alt":[],"source":"krupnik","glosses":[{"text":"a locust","label":""}],"html":"<p>מין ארבה a locust  שבת צ׳ ע״ב: צפורת כרמים – פליא ביארי.</p>","notation":["ז׳"]},"44395":{"h":"פַּלְיוּם","r":"KRU15559","alt":[],"source":"krupnik","glosses":[{"text":"sheet, blanket","label":""}],"html":"<p>סדין sheet, blanket  נדה פ״ה מ״א ומתכסה בו בלילה וכו׳ וכן בפליום.</p>","notation":["ז׳"]},"44396":{"h":"פִּלְיוֹן","r":"KRU15560","alt":[],"source":"krupnik","glosses":[{"text":"felt-cape","label":""}],"html":"<p>כובע של לבד felt-cape  כל׳ פכ״ט מ״א: והפליון של ראש.</p>","notation":["ז׳"]},"44397":{"h":"פליטה","r":"KRU15561","alt":[],"source":"krupnik","glosses":[{"text":"name of an Amora","label":""}],"html":"<p>שם אמורא name of an Amora  ירוש׳ תענ׳ פ״ד ס״ח ע״ד: התיב רבי פליטה בר פריטה קומי רבי זעורה (ובדפוס ראשון: פליפה).</p>","notation":["Source emendation: פְּלִיפָּא"]},"44398":{"h":"פליטורין","r":"KRU15563","alt":[],"source":"krupnik","glosses":[{"text":"ware","label":""}],"html":"<p>סחורה ware  ירוש׳ ב״מ פ״ב ט׳ ע״ב: בר נש דיהב לחבריה פליטורין בשוקא.</p>","notation":["ז״ר","Source emendation: פּוֹלִיטֵירִין"]},"44399":{"h":"פְּלֵיטִית","r":"KRU15565","alt":[],"source":"krupnik","glosses":[{"text":"a woman’s name","label":""}],"html":"<p>שם אשה a woman’s name  תרג׳ יב״ע בר׳ י״ח כ״א: כקיבלתא דריבה פליטית.</p>","notation":[]},"44400":{"h":"פְּלִימוֹ","r":"KRU15568","alt":[],"source":"krupnik","glosses":[{"text":"name of a Tannai","label":""}],"html":"<p>שם תנא name of a Tannai  פס׳ ח׳ ע״ב: דתניא וכו׳ פלימו אמר.</p>","notation":[]},"44401":{"h":"פִּלִיפִּי","r":"KRU15572","alt":[],"source":"krupnik","glosses":[{"text":"name of an Amora","label":""}],"html":"<p>שם אמורא name of an Amora  ב״ר פע״א: א״ר פליפי בר נהוראי.</p>","notation":[]},"44402":{"h":"פלירכוס","r":"KRU15573","alt":[],"source":"krupnik","glosses":[{"text":"governor","label":""}],"html":"<p>שר העיר governor  ילק׳ דב׳ תתי״ג: אפוטרופוס גוזר גזרה פלירכוס מבטל על ידיו פלירכוס גוזר גזרה דיקוריון מבטל על ידיו וכו׳.</p>","notation":["ז׳","Source emendation: פּוֹלְיַרְכוֹס"]},"44403":{"h":"פְּלַל","r":"KRU15575","alt":[],"source":"krupnik","glosses":[{"text":"to debate","label":""}],"html":"<p>התוכח, התפלפל to debate  ירוש׳ שבי׳ פ״ח ל״ה ע״ב: מאן גרם לך דלא פלתה עם חביריך.</p>","notation":["פ״ע"]},"44404":{"h":"פְּלַלְגוּלָה","r":"KRU15576","alt":[],"source":"krupnik","glosses":[{"text":"onion","label":""}],"html":"<p>מין בצל קטן onion  ירוש׳ כלא׳ פ״א כ״ז ע״א: בצלצול – פללגולה.</p>","notation":["נ׳"]},"44405":{"h":"פַּלְמוּדָא","r":"KRU15577","alt":[],"source":"krupnik","glosses":[{"text":"a fish","label":""}],"html":"<p>מין דג a fish  ע״ז מ׳ ע״א: בארא ופלמודא דדמו רישייהו לטמאים.</p>","notation":["ז׳"]},"44406":{"h":"פַּלְמַנְטְרִין","r":"KRU15580","alt":[],"source":"krupnik","glosses":[{"text":"agent","label":""}],"html":"<p>שליח agent  תנח׳ במ׳ כ״ו: אף אני מקרבו ועושה פלמנטרין שלי.</p>","notation":["ז׳"]},"44407":{"h":"פְּלַן","r":"KRU15584","alt":[],"source":"krupnik","glosses":[{"text":"such and such, certain","label":""}],"html":"<p>פלוני such and such, certain  ירוש׳ יב׳ פ״ד ו׳ ע״א: ביום פלן; קיד׳ פ״ג ס״ג ע״ב: אנא פלן בר פלן מקדש ליך אנת פלנית.</p>","notation":["מה״ג"]},"44408":{"h":"פְּלָנִי","r":"KRU15587","alt":[],"source":"krupnik","glosses":[{"text":"planet","label":""}],"html":"<p>כוכב planet  תנח׳ צו ג׳: רמז לכבשן ונעשה פלני.</p>","notation":["ז׳"]},"44409":{"h":"פלנים","r":"KRU15589","alt":[],"source":"krupnik","glosses":[{"text":"a cloak","label":""}],"html":"<p>מין בגד a cloak  ירוש׳ חג׳ פ״א ע״ו ע״ד: מהו להתיר בפלנים וכו׳ במקום שאין טלית.</p>","notation":["ז׳","Source emendation: פִּינוֹלֵס"]},"44410":{"h":"פְּלַס","r":"KRU15590","alt":[],"source":"krupnik","glosses":[{"text":"to pick to pieces","label":"פַעל,"}],"html":"<p>פַעל, פַּלֵס קרע לגזרים to pick to pieces  ב״ק י״ט ע״ב: ופלסיה לסלא: שם: לפלוסי סלא.</p>","notation":[]},"44411":{"h":"פְּלַסְגָּר","r":"KRU15591","alt":[],"source":"krupnik","glosses":[{"text":"flask","label":""}],"html":"<p>בקבוק flask  תוס׳ צוק׳ תר׳ ז׳ ט״ז: לגין וכו׳ ובפלסגר.</p>","notation":["ז׳"]},"44412":{"h":"פְּלַסּוֹן","r":"KRU15592","alt":[],"source":"krupnik","glosses":[{"text":"protector","label":""}],"html":"<p>מגין protector  ב״ר פ״ס: הוא ופלסונו.</p>","notation":["ז׳"]},"44413":{"h":"פְּלַסְטוֹן","r":"KRU15593","alt":[],"source":"krupnik","glosses":[{"text":"fraud","label":""}],"html":"<p>דבר מעושה ובדוי. רמאות fraud  במ״ר פ״ח: היו אומות העולם אומרים תורתן של אלו פלסטון.</p>","notation":["ז׳"]},"44414":{"h":"פְּלַסְטִינֵי","r":"KRU15594","alt":[],"source":"krupnik","glosses":[{"text":"Palestine","label":""}],"html":"<p>פלשת, ארץ ישראל Palestine  ב״ר פ״צ: בפיניקיא ובערביא ובפלסטיני.</p>","notation":[]},"44415":{"h":"פְּלַסְלוֹס","r":"KRU15597","alt":[],"source":"krupnik","glosses":[{"text":"a species of beans","label":""}],"html":"<p>מין פול a species of beans  כלא׳ פ״א מ״ג: התורמוס והפלסלוס.</p>","notation":["ז׳"]},"44416":{"h":"פַּלְסְמוֹן","r":"KRU15598","alt":[],"source":"krupnik","glosses":[{"text":"balm","label":""}],"html":"<p>שמן אפרסמון balm  במ״ר פ״ג: לא בפלסמון ולא ראשי בשמים.</p>","notation":["ז׳"]},"44417":{"h":"פִּלְפּוּל","r":"KRU15600","alt":["פִּלְפּוּלָא"],"source":"krupnik","glosses":[{"text":"dialectics","label":""}],"html":"<p>וכוח חריף, ניצוח dialectics  ב״ב קמ״ה ע״ב: בעל פלפול; עיר׳ ס״ז ע״ב: מפלפולא דרב חסדא.</p>","notation":[]},"44418":{"h":"פִּלְפֵּל","r":"KRU15602","alt":[],"source":"krupnik","glosses":[{"text":"to debate","label":"1"},{"text":"to quarrel","label":"2"}],"html":"<p>1 התוכח to debate  שבת ל״א ע״א: פלפלת בחכמה.\n2 רב ודן, התקוטט to quarrel  תוס׳ ב״מ ז׳ ה׳: שלא פלפלו בו יתומין אחר מיתת אביהם.</p>","notation":["פ״ע"]},"44419":{"h":"פַּלְפֵּל","r":"KRU15603","alt":[],"source":"krupnik","glosses":[{"text":"to roll","label":""},{"text":"to roll onself","label":""}],"html":"<p>1) בנ״ל 1. תרג׳ איוב י״א י״ב (ואיש נבוב ילבב): ובר נש מפלפל ודייק. 2) הכפיש to roll  שם ט״ז ט״ו (ועוללתי בעפר קרני): ופלפלית בעפרא איקרי. אִתְפַּלְפֵּל אתפ׳, התפלש to roll onself  תרג׳ שני אס׳ ד׳ א׳: אתפלפל בקיטמא. </p>","notation":["פעו״י"]},"44420":{"h":"פִּלְפָּל","r":"KRU15604","alt":["פִּלְפְּלָא"],"source":"krupnik","glosses":[{"text":"grain of pepper","label":""}],"html":"<p>גרעין של התבלין החריף הידוע grain of pepper  שבת ס״ד ע״ב: פלפל לריח הפה; כת׳ ע״ה ע״א: דנקיט פלפלא בפומיה.</p>","notation":[]},"44421":{"h":"פִּלְפְּלָן","r":"KRU15605","alt":[],"source":"krupnik","glosses":[{"text":"dialectitian","label":""}],"html":"<p>בעל פלפול dialectitian  ירוש׳ הור׳ פ״ג מ״ח ע״ג: דהוא סדרן והוא פלפלן.</p>","notation":["ז׳"]},"44422":{"h":"פִּלָצוּר","r":"KRU15607","alt":[],"source":"krupnik","glosses":[{"text":"a snare","label":""}],"html":"<p>מין רשת ומצודה a snare  כל׳ פכ״ג מ״ה: המדף והפלצור.</p>","notation":["ז׳"]},"44423":{"h":"פַּלְקָא","r":"KRU15608","alt":[],"source":"krupnik","glosses":[{"text":"scratch","label":""}],"html":"<p>שריטה scratch  קהל״ר ו׳ י״א: חד פלקא או חד פצעה.</p>","notation":["ז׳"]},"44424":{"h":"פַּלְקְתָא","r":"KRU15609","alt":[],"source":"krupnik","glosses":[{"text":"concubine","label":""}],"html":"<p>פילגש concubine  תרג׳ דהי״א א׳ ל״ב (פילגש): פלקתא.</p>","notation":["נ׳"]},"44425":{"h":"פָּלַשׁ","r":"KRU15610","alt":[],"source":"krupnik","glosses":[{"text":"to search","label":""}],"html":"<p>בדק וחיפש to search  ירוש׳ סנה׳ פ״י כ״ט ע״ב: עלי לפלש להם מעשים טובים.</p>","notation":["פ״י"]},"44426":{"h":"פִּלֵּשׁ","r":"KRU15611","alt":[],"source":"krupnik","glosses":[{"text":"to go through, to perforate","label":"פיעל,"}],"html":"<p>פיעל, חדר ועבר to go through, to perforate  ירוש׳ סוכה פ״ג נ״ג ע״ד: ניקב ולא פילש.</p>","notation":[]},"44427":{"h":"פָּמוֹט","r":"KRU15616","alt":[],"source":"krupnik","glosses":[{"text":"a candlestick","label":""}],"html":"<p>מין מנורה a candlestick  שבת מ״ד ע״א: פמוט שהדליקו עליו באותה שבת.</p>","notation":["ז׳"]},"44428":{"h":"פַּמַּלְיָא","r":"KRU15622","alt":[],"source":"krupnik","glosses":[{"text":"attendants of the king","label":""}],"html":"<p>חבר משרתי המלך attendants of the king  במ״ר פ״ד: ראה המלך ופמליא שלו.</p>","notation":["נ׳"]},"44429":{"h":"פמליאות","r":"KRU15623","alt":[],"source":"krupnik","glosses":[{"text":"a cloak","label":""}],"html":"<p>מין מלבוש a cloak  תוס׳ כל׳ ב״ב ה׳ י״א: הפמליאות וההמילות וכו׳.</p>","notation":["נ״ר","Source emendation: פִּינוֹלָאוֹת"]},"44430":{"h":"פִּמְלַלְיָא","r":"KRU15624","alt":["פִּמְלַנְיָא"],"source":"krupnik","glosses":[{"text":"knee-breeches","label":""}],"html":"<p>מכנסים עד הברכים knee-breeches  ב״ר פפ״ד: אשר עליו – זו פמלניא שלו; שם פצ״ט: אלו לובשים מכנסים ואלו לובשים פמלליא.</p>","notation":[]},"44431":{"h":"פְּנַאי","r":"KRU15626","alt":[],"source":"krupnik","glosses":[{"text":"emptiness, vacancy","label":"1"},{"text":"time, leisure","label":"2"}],"html":"<p>1 ריקנות emptiness, vacancy  במ״ר פי״ד: לא נתבהל מפנאי הבית.\n2 זמן פנוי time, leisure  מו״ק י״ז ע״ב: בשלא היה להם פנאי או דילמא אף כשהיה להם פנאי.</p>","notation":["ז׳"]},"44432":{"h":"פנגוס","r":"KRU15627","alt":["פנגס"],"source":"krupnik","glosses":[{"text":"pledge","label":""}],"html":"<p>משכון pledge  מכי׳ יתרו בחודש פרשה א׳: לא נתתיה פנגוס וכו׳ כבר עד שלא נתתי לכם המצות הקדמתי לכם מתן שכרם; ילק׳ שמות רע״ה: לא נתתיה פנגוס.</p>","notation":[]},"44433":{"h":"פַּנְגַּר","r":"KRU15628","alt":[],"source":"krupnik","glosses":[{"text":"a man’s name","label":""}],"html":"<p>a man’s name  איכ״ר א׳ ה׳: מן דכבשה פלוג ארבע טכסיא לארבעה דוכסיא וסליק פילי מערבאה לפנגר. </p>","notation":["שם איש"]},"44434":{"h":"פַּנְדָּא","r":"KRU15629","alt":[],"source":"krupnik","glosses":[{"text":"handle of a tool","label":"1"},{"text":"blow","label":"2"},{"text":"name of an Amora","label":"3"}],"html":"<p>1 בית יד של גרזן וכדומה handle of a tool  ב״ק כ״ז ע״ב: שקל פנדא דמרא מחייה.\n2 מכה blow  שם: מאה פנדי בפנדא.\n3 שם אמורא name of an Amora  בר׳ נ״ה ע״ב: אמר ר׳ פנדא וכו׳.</p>","notation":["ז׳"]},"44435":{"h":"פנדודה","r":"KRU15630","alt":["פַּנְדוּר","פַּנְדּוּרָה"],"source":"krupnik","glosses":[{"text":"the shepherd’s pipe","label":""}],"html":"<p>חליל רועה, the shepherd’s pipe  ירוש׳ ב״ב פ״ג י״ג ע״ד: משכוכיתא – אית דמרין פנדודה; שם פ״ז ט״ו ע״ד: נותן לו כמין פנדור; ב״ק פ״י ז׳ ע״ג: אית דמרין פנדורה.</p>","notation":[]},"44436":{"h":"פַּנְדֵּירָא","r":"KRU15631","alt":["פַּנְדֵּרָא"],"source":"krupnik","glosses":[{"text":"surname of Joseph the father of Jesus of Nazareth","label":""}],"html":"<p>כנוי ליוסף אבי ישו הנוצרי surname of Joseph the father of Jesus of Nazareth  שבת ק״ד ע״ב: בן פנדירא (בהו׳ אח׳: סטדא); ירוש׳ ע״ז ע״ב מ״ב מ׳ ע״ד: ישו בן פנדרא.</p>","notation":[]},"44437":{"h":"פָּנָה","r":"KRU15633","alt":[],"source":"krupnik","glosses":[{"text":"to ease nature","label":""},{"text":"to turn","label":""},{"text":"to have leisure","label":""},{"text":"to be removed","label":""},{"text":"to ease nature","label":""}],"html":"<p>עשה צרכיו to ease nature  טהר׳ פ״י מ״ב: פונין לאחורי הגדר. נִפְנָה נפ׳, 1) פנה to turn  תענ׳ ל״א ע״א: כל שאין לו אשה נפנה לשם. 2) היה פנוי מעסקיו to have leisure  אבות פ״ב מ״ד: ואל תאמר לכשאפנה אשנה שמא לא תפנה. 3) נתבער ונסתלק to be removed  ב״ק ל״ב ע״ב: באשפה העשויה להפנות בלילה. 4) יצא לצרכיו to ease nature  בר׳ ס״ב ע״א: איזהו צנוע זה הנפנה בלילה במקום שנפנה ביום. </p>","notation":["Marked biblical in source"]},"44438":{"h":"פִּנָּה","r":"KRU15634","alt":[],"source":"krupnik","glosses":[{"text":"to free","label":"פיעל"}],"html":"<p>פיעל ·– שחרר to free  במ״ר פ״ה: בשביל בני אני מפנה אותם.\nהִתְפַּנָּה התפ׳, עי׳ נִפְנָה 3. ירוש׳ נזיר פ״ט נ״ז ע״ד: כל הקברות מתפנין וכו׳. </p>","notation":[]},"44439":{"h":"פִּנוּי","r":"KRU15635","alt":[],"source":"krupnik","glosses":[{"text":"clearing","label":""}],"html":"<p>ביעור clearing  נגע׳ פי״ב מ״ה: עסק הוא לפנוי.</p>","notation":["ז׳"]},"44440":{"h":"פָּנוּי","r":"KRU15636","alt":[],"source":"krupnik","glosses":[{"text":"empty","label":"1"},{"text":"free","label":"2"},{"text":"single, unmarried","label":"3"}],"html":"<p>1 ריקן empty  עיר׳ י״ז ע״א: פנוי מאדם וכו׳ פנוי מכלים.\n2 חפשי free  תנח׳ וארא ו׳: פנוי היה מעבודת פרך.\n3 בלתי נשוי single, unmarried  ירוש׳ יבמ׳ פ״ו ז׳ ע״ג: הפנוי הבא על הפנויה שלא לשם אישות הרי זו בעילת זנות.</p>","notation":["ת׳"]},"44441":{"h":"פְּנַהְיָא","r":"KRU15638","alt":[],"source":"krupnik","glosses":[{"text":"protection","label":""}],"html":"<p>בטיחות protection  ב״ק ק״ג ע״א: מידע ידעת דאנא לנפשאי שקילנא ופנהיא בעלמא הוא דקבעינא.</p>","notation":["ז׳"]},"44442":{"h":"פַּנְטוֹן","r":"KRU15639","alt":[],"source":"krupnik","glosses":[{"text":"of all","label":""}],"html":"<p>של הכל of all  אסת״ר ו׳ י׳: דומין פנטון.</p>","notation":["מה״ג"]},"44443":{"h":"פַּנְטוֹס","r":"KRU15640","alt":[],"source":"krupnik","glosses":[{"text":"at all events","label":""}],"html":"<p>בכל אופן at all events  ירוש׳ סנה׳ פ״ו כ״ג ע״ב: פנטוס דמיתפס חד מנכון.</p>","notation":["תה״פ"]},"44444":{"h":"פַּנְטֵי","r":"KRU15641","alt":[],"source":"krupnik","glosses":[{"text":"to go) to meet","label":""}],"html":"<p>לקראת (to go) to meet  ירוש׳ ע״ז פ״ב מ״א ע״ב: ר׳ יוחנן נפק לפנטי דר׳ יודן נשייא לעכו.</p>","notation":["מה״י","Used in: לְפַנְטֵי"]},"44445":{"h":"פַּנְטִי","r":"KRU15642","alt":[],"source":"krupnik","glosses":[{"text":"a man’s name","label":""}],"html":"<p>a man’s name  קהל״ר ח׳ ג׳: לוי בן פנטי. </p>","notation":["שם איש"]},"44446":{"h":"פֶּנְטִיגִין","r":"KRU15643","alt":[],"source":"krupnik","glosses":[{"text":"pentagonal","label":""}],"html":"<p>בן חמש זויות pentagonal  תוס׳ צוק׳ נגע׳ ו׳ ג׳: דיגין טריגין פנטיגין וכו׳.</p>","notation":["ת׳"]},"44447":{"h":"פַּנְטֵירִי","r":"KRU15644","alt":[],"source":"krupnik","glosses":[{"text":"a jewel","label":"2"}],"html":"<p>1 עי׳ פַּנְדֵּירָא. תוס׳ חול׳ ב׳ כ״ד: ואמר דבר של מינות משום ישוע בן פנטירי. \n2 מין אבן טובה a jewel  תרג׳ שמ׳ ל״ט י״ג (וישפה): ופנטירי.</p>","notation":[]},"44448":{"h":"פֶּנְטַקָּקָה","r":"KRU15645","alt":[],"source":"krupnik","glosses":[{"text":"surname of one who had committed five sins every day","label":""}],"html":"<p>כנוי לאדם שעבר חמש עבירות בכל יום surname of one who had committed five sins every day  ירוש׳ תענ׳ פ״א ס״ד ע״ג: פנטקקה יצלי וכו׳ חמש עבירן ההוא גוברא עביד בכל יום.</p>","notation":[]},"44449":{"h":"פַּנְיָא","r":"KRU15647","alt":[],"source":"krupnik","glosses":[{"text":"empty","label":"1"},{"text":"evening","label":"2"}],"html":"<p>1  empty  ב״ר פס״ה: לא דמי ההוא דחמי סולגיתא פניא וכפן לההוא דחמי סולגיתא מליא ושבע.\n2  evening  ב״מ מ״ט ע״א: אפניא דמעלי שבתא הוה.</p>","notation":[]},"44450":{"h":"פַּנְיָאס","r":"KRU15648","alt":[],"source":"krupnik","glosses":[{"text":"name of a place in Palestine","label":""}],"html":"<p>בארץ ישראל name of a place in Palestine  ב״ר פס״ג: יתיב בהדא פניאס.</p>","notation":["שם מקום"]},"44451":{"h":"פְּנִיּוּתָא","r":"KRU15649","alt":[],"source":"krupnik","glosses":[{"text":"leisure","label":""}],"html":"<p>פנאי leisure  תרג׳ יב״ע ויק׳ כ׳ ו׳: ואנא אתן פניותא למעסוק בגברא ההוא.</p>","notation":["נ׳"]},"44452":{"h":"פָּנִים","r":"KRU15652","alt":[],"source":"krupnik","glosses":[{"text":"manner, aspect","label":"1"}],"html":"<p>1 דרך ואופן manner, aspect  במ״ר פ״ב: תורה שהיא נדרשת מ״ט פנים.\n2 עי׳ פָּנִים שֶׁל מַטָּה. בר׳ כ״ד ע״א: פניה טוחות בקרקע. </p>","notation":[]},"44453":{"h":"פָּנִים חֲדָשׁוֹת","r":"KRU15653","alt":[],"source":"krupnik","glosses":[{"text":"new guest","label":"1"},{"text":"an object that assumed a new appearance","label":"2"}],"html":"<p>1 אדם חדש, אורח חדש new guest  כת׳ ז׳ ע״ב: ברכת חתנים בעשרה כל שבעה וכו׳ והוא שבאו פנים חדשות.\n2 דבר בצורה חדשה an object that assumed a new appearance  ב״ק צ״ו ע״ב: האי מאן דגזל נסכא מחבריה ועביד זוזי וכו׳ זוזי ועבדינהו נסכא וכו׳ פנים חדשות באו לכאן.</p>","notation":[]},"44454":{"h":"פָּנִים שֶׁל מַטָּה","r":"KRU15654","alt":[],"source":"krupnik","glosses":[{"text":"pudenda","label":""}],"html":"<p>בית הבושת pudenda  שבת מ״א ע״א: המניח ידיו כנגד פניו של מטה.</p>","notation":[]},"44455":{"h":"לְפָנִים","r":"KRU15655","alt":[],"source":"krupnik","glosses":[{"text":"for show","label":""}],"html":"<p>כלפי חוץ, למראית עין for show  מגי׳ י״ב ע״א: הם לא עשו אלא לפנים.</p>","notation":["תה״פ","Marked biblical in source"]},"44456":{"h":"מִפְּנֵי שֶ־","r":"KRU15656","alt":[],"source":"krupnik","glosses":[{"text":"because","label":""}],"html":"<p>לפי ש־, מכיון ש־ because  שבת פ״ב מ״ה: מפני שהוא מתיירא מפני גויים</p>","notation":[]},"44457":{"h":"פְּנִים","r":"KRU15657","alt":[],"source":"krupnik","glosses":[{"text":"inside","label":""},{"text":"inside","label":""},{"text":"within","label":""},{"text":"in the Holy of Holies","label":""},{"text":"inside the line of the law, equity","label":""}],"html":"<p>בִּפְנִים בתוך, בקרב inside  חול׳ ע״ח ע״א: בפנים ובחוץ. לִפְנִים  1) כלפי פנים, אל תוך inside  ב״מ ט״ז ע״א: זו אינה צריכה לפנים. 2) תוך within  ב״ר פכ״א: שהיתה מחיצתו לפנים ממלאכי השרת. לִפְנַי וְלִפְנִים בבית קדשי הקדשים in the Holy of Holies  זבח׳ נ״ז ע״א: כשם שמזה לפני ולפנים וכו׳. לְפְנִים מִשּׁוּרַת הַדִּין שלא כחומר הדין inside the line of the law, equity  ב״מ ל׳ ע״ב: דין תורה וכו׳ לפנים משורת הדין. מִבִּפְנִים עי׳ בִּפְנִים (פְּנִים). ירוש׳ כלא׳ פ״ח ל״א ע״ג: מבפנים וכו׳ מבחוץ. </p>","notation":["Marked biblical in source"]},"44458":{"h":"פְּנִימוֹן","r":"KRU15658","alt":[],"source":"krupnik","glosses":[{"text":"name of a Tannai","label":""}],"html":"<p>שם תנא name of a Tannai  ירוש׳ תר׳ פ״ג מ״ב ע״ב: מאן דמר עובר רבנין מאן דמר אינו עובר אבא פנימון.</p>","notation":[]},"44459":{"h":"פַּנִּיקְטִין","r":"KRU15659","alt":[],"source":"krupnik","glosses":[{"text":"camps","label":""}],"html":"<p>מחנות camps  ויק״ר פ״א: היו אומות העולם שומעין קול הדבור ונתרזין מתוך פניקטיהן.</p>","notation":["ז״ר"]},"44460":{"h":"פְּנִיקְיָא","r":"KRU15660","alt":[],"source":"krupnik","glosses":[{"text":"Phoenica","label":""}],"html":"<p>ארץ צור וצידון Phoenica  ב״ר פ״צ: בשלש ארצות בפניקיא ובפלסטיני ובערביא.</p>","notation":[]},"44461":{"h":"פַּנֵךְ","r":"KRU15661","alt":[],"source":"krupnik","glosses":[{"text":"to drive on","label":"פַעל,"}],"html":"<p>פַעל, דפק בסוסים to drive on  תרג׳ שופ׳ ה׳ כ״ב: מפינוכא דהוה מפנך.</p>","notation":[]},"44462":{"h":"פָּנָס","r":"KRU15663","alt":[],"source":"krupnik","glosses":[{"text":"lantern","label":""}],"html":"<p>מנורה עשויה לשאתה בחוץ lantern  שמו״ר פט״ו: היה נוטל הפנס ומהלך לפניהם.</p>","notation":["ז׳"]},"44463":{"h":"פַּנֵּק","r":"KRU15664","alt":[],"source":"krupnik","glosses":[{"text":"to treat tenderly","label":""},{"text":"to delight oneself","label":""}],"html":"<p>עידן to treat tenderly  תרג׳ אס׳ ב׳ ט׳: למוטבא להון ולפנקותהון. אִתְפַּנֵּק אתפ׳, התענג to delight oneself  תרג׳ תה׳ ל״ז י״א (והתענגו על רוב שלום): ויתפנקון על סגיאות שלמא. </p>","notation":["פַעל"]},"44464":{"h":"פִּנְקַאי","r":"KRU15665","alt":[],"source":"krupnik","glosses":[{"text":"a man’s name","label":""}],"html":"<p>a man’s name  פס׳ נ״ז ע״א: יוחנן בן נרבאי תלמידו של פנקאי. </p>","notation":["שם איש"]},"44465":{"h":"פִּנְקֵס","r":"KRU15666","alt":[],"source":"krupnik","glosses":[{"text":"pinax","label":"1"},{"text":"book","label":"2"}],"html":"<p>1 לוח pinax  שבת פי״ב מ״ה: שני דפי פנקס.\n2 ספר book  אבות פ״ג מט״ז: הפנקס פתוח והיד כותבת.</p>","notation":["ז׳"]},"44466":{"h":"פַּנְקְרִיסִין","r":"KRU15668","alt":["פַּנְקְרִסִּין"],"source":"krupnik","glosses":[{"text":"cakes","label":""}],"html":"<p>מין מאפה cakes  ירוש׳ ע״ז פ״ב מ״א ע״ג: ופנקריסין וכו׳ וקליות וכו׳; סוטה פ״א י״ז ע״ב: יפה סיפסוף שאכלנו בנעורינו מפנקרסין שאכלנו בזקנותינו.</p>","notation":[]},"44467":{"h":"פִּנְתָא","r":"KRU15669","alt":[],"source":"krupnik","glosses":[{"text":"corner","label":""}],"html":"<p>פנה, קרן זוית corner  תרג׳ מש׳ ז׳ י״ב (פנה): פנתא.</p>","notation":["נ׳"]},"44468":{"h":"פַּנְתָּא","r":"KRU15670","alt":[],"source":"krupnik","glosses":[{"text":"a shoe","label":""}],"html":"<p>מין נעל a shoe  בר׳ מ״ג ע״ב: ולא אמרן אלא בפנתא.</p>","notation":["נ׳"]},"44469":{"h":"פָּנְתּוֹס","r":"KRU15671","alt":[],"source":"krupnik","glosses":[{"text":"Pontus","label":""}],"html":"<p>שם ארץ על חוף הים השחור Pontus  ילק׳ ויק׳ תרנ״ט: מה שהוציא עקילס לעבדיו לפנתוס.</p>","notation":[]},"44470":{"h":"פַּנְתֵּירִי","r":"KRU15672","alt":[],"source":"krupnik","glosses":[{"text":"a jewel","label":""}],"html":"<p>מין אבן טובה a jewel  תרג׳ שמ׳ ל״ט י״ג (וישפה): ופנתירי.</p>","notation":["ז׳"]},"44471":{"h":"פַּנְתֵּירִין","r":"KRU15673","alt":[],"source":"krupnik","glosses":[{"text":"panther","label":""}],"html":"<p>מין חיה טורפת panther  מדר׳ תה׳ ע״ח מ״ה; ערוב – מין חיה הוא ושמה פנתירין.</p>","notation":["ז׳"]},"44472":{"h":"פָּס","r":"KRU15674","alt":[],"source":"krupnik","glosses":[{"text":"name of Amoraim","label":""}],"html":"<p>שם אמוראים name of Amoraim  ירוש׳ יומא פ״ה מ״ג ע״א: ר׳ הושעיה בשם רבי פס.</p>","notation":[]},"44473":{"h":"פַּס","r":"KRU15675","alt":[],"source":"krupnik","glosses":[{"text":"stripe","label":"1"},{"text":"the palm of the hand or the foot","label":"2"},{"text":"pole","label":"3"},{"text":"tax","label":"4"}],"html":"<p>1 רצועה stripe  ב״ר פפ״ד: שיקרע הים לפניהם פסים פסים.\n2 כף יד או רגל the palm of the hand or the foot  ילק׳ שמואל קמ״ג: פס יד ופס רגל ועקב מגולין.\n3 מוט pole  עיר׳ י׳ ע״ב: עושה פס גבוה עשרה.\n4 מס tax  ירוש׳ פאה פ״ח כ״א ע״א: לפסין ולצדקות.</p>","notation":["Marked biblical in source"]},"44474":{"h":"פִּסֵּג","r":"KRU15676","alt":[],"source":"krupnik","glosses":[{"text":"to split","label":"פיעל"},{"text":"to cut one's way through","label":"הִפְסִיג הפ׳,"}],"html":"<p>פיעל ·– ביקע to split  פרה פי״א מ״ט: מפסגו ואוגדו.\nהִפְסִיג הפ׳, חדר ועבר to cut one&#x27;s way through  ב״ק פ״א ע״ב: מפסיג ויורד מפסיג ועולה.</p>","notation":[]},"44475":{"h":"פְּסַג","r":"KRU15677","alt":[],"source":"krupnik","glosses":[{"text":"to escape","label":"2"}],"html":"<p>1 כנ״ל. ב״ר פ״ק: פסיג תרעך. \n2 נמלט to escape  ב״ר פע״ט: כד שמע וכו׳ פסגא.</p>","notation":["פעו״י"]},"44476":{"h":"פִּסְגָא","r":"KRU15678","alt":[],"source":"krupnik","glosses":[{"text":"piece","label":""}],"html":"<p>בתר piece  תרג׳ ירוש׳ בר׳ כ״ו ל״א: פסגא חדא.</p>","notation":["ז׳"]},"44477":{"h":"פָּסֵד","r":"KRU15679","alt":[],"source":"krupnik","glosses":[{"text":"to spoil","label":""},{"text":"to suffer loss","label":""},{"text":"to cause loss to","label":""}],"html":"<p>נתקלקל to spoil  ירוש׳ מעש׳ פ״ה נ״א ע״ג: חטין אינן פסידין. נִפְסַד נפ׳, עי׳ הִפְסִיד 1. פס׳ ג׳ ע״ב: יש זריז ונשכר ויש זריז ונפסד. הִפְסִיד הפ׳, 1) אבד לו, ניזק to suffer loss  ב״ר פ״ע: שנים נדרו והפסידו שנים נדרו ונשתכרו. 2) הזיק to cause loss to  תוס׳ ביצה ב׳ ו׳: שמא יפסידו את בני העיר. </p>","notation":["פ״ע"]},"44478":{"h":"פָּסָה","r":"KRU15681","alt":[],"source":"krupnik","glosses":[{"text":"to spread","label":""}],"html":"<p>פשה ורבה, התפשט to spread  ירוש׳ מו״ק פ״א פ׳ ע״ג: בהרת כגריס ופסתה כגריס.</p>","notation":["פ״ע"]},"44479":{"h":"פְּסוּגָא","r":"KRU15683","alt":[],"source":"krupnik","glosses":[{"text":"piece","label":""}],"html":"<p>בתר piece  תרג׳ דהי״א ז׳ כ״א: ביני פסוגיא.</p>","notation":["ז׳"]},"44480":{"h":"פסוורוס","r":"KRU15685","alt":[],"source":"krupnik","glosses":[{"text":"name of a tortuous street","label":""}],"html":"<p>שם רחוב מעוקם ומפותל name of a tortuous street  ירוש׳ ע״ז פ״א מ׳ ע״א: דרך עקמומית היתה כגון אהין פסוורוס.</p>","notation":["Source emendation: פִּוְוסָרוֹס"]},"44481":{"h":"פָּסוּל","r":"KRU15686","alt":[],"source":"krupnik","glosses":[{"text":"unfit, defective, disqualified","label":""}],"html":"<p>אינו כשר, פגול, אינו ראוי unfit, defective, disqualified  הפסולין ששחטו שחיטתן כשרה; ירוש׳ קיד׳ פ״ג ס״ד ע״ג: כשרין הוזהרו על הפסולין.</p>","notation":["ת׳"]},"44482":{"h":"פְּסוּל","r":"KRU15687","alt":[],"source":"krupnik","glosses":[{"text":"blemish, disqualification","label":""}],"html":"<p>חסרון, מום blemish, disqualification  תוס׳ מקוא׳ א׳ י״ט: מקוה פסולו בעצמו ובעל מום פסולו בגופו.</p>","notation":["ז׳"]},"44483":{"h":"פְּסוּלָא","r":"KRU15688","alt":[],"source":"krupnik","glosses":[{"text":"dross","label":"2"}],"html":"<p>1 כנ״ל. כת׳ ס״ב ע״ב: חס ושלום פסולא איכא. \n2 סיגים dross  תרג׳ יש׳ א׳ כ״ב (לסיגים): לפסולא.</p>","notation":["ז׳"]},"44484":{"h":"פְּסוֹלֶת","r":"KRU15689","alt":[],"source":"krupnik","glosses":[{"text":"chips","label":"1"},{"text":"worthless matter","label":"2"}],"html":"<p>1 מפל הפיסול chips  ירוש׳ שק׳ פ״ה מ״ט ע״א: מפסולת הלוחות העשיר משה וכו׳ פסל לך שתהא הפסולת שלך.\n2 דבר פחות worthless matter  במ״ר פט״ז: שכן התגרין מראין את הפסולת תחלה ואח״כ מראין את השבח.</p>","notation":["נ׳"]},"44485":{"h":"פָּסוּק","r":"KRU15691","alt":["פְּסוּקָא"],"source":"krupnik","glosses":[{"text":"Biblical verse","label":""}],"html":"<p>חרוז ומאמר במקרא Biblical verse  סנה׳ צ״ט ע״א: אפילו אמר כל התורה כולה מן השמים חוץ מפסוק זה; מגי׳ כ״ב ע״א: כל פסוקא דלא פסקיה משה אנן לא פסקינן ליה.</p>","notation":[]},"44486":{"h":"פֶּסַח פֶּסַח דּוֹרוֹת","r":"KRU15692","alt":[],"source":"krupnik","glosses":[{"text":"the annual Passover celebration","label":""}],"html":"<p>חגיגת הפסח הרגילה בכל שנה ושנה the annual Passover celebration  פס׳ צ״ו ע״א: פסח דורות וכו׳ פסח מצרים.</p>","notation":["Marked biblical in source"]},"44487":{"h":"פֶּסַח מִצְרַיִם","r":"KRU15693","alt":[],"source":"krupnik","glosses":[{"text":"the Passover observed in Egypt","label":""}],"html":"<p>חגיגת הפסח בזמן צאת ישראל ממצרים the Passover observed in Egypt  פסח׳ צ״ו ע״א: פסח דורות וכו׳ פסח מצרים.</p>","notation":[]},"44488":{"h":"פֶּסַח רִאשׁוֹן","r":"KRU15695","alt":[],"source":"krupnik","glosses":[{"text":"the first Passover, celebrated on the fourteenth of Nisan","label":""}],"html":"<p>חג הפסח העקרי, בי״ד בניסן the first Passover, celebrated on the fourteenth of Nisan  פס׳ צ״ה ע״ב: פסח ראשון וכו׳.</p>","notation":[]},"44489":{"h":"פֶּסַח שֵׁנִי","r":"KRU15696","alt":[],"source":"krupnik","glosses":[{"text":"the second (vicarious) Passover on the fourteenth of Iyar","label":""}],"html":"<p>חגיגת הפסח בי״ד אייר בשביל הבאים מדרך רחוקה the second (vicarious) Passover on the fourteenth of Iyar  פס׳ צ״ה ע״ב: פסח שני וכו׳.</p>","notation":[]},"44490":{"h":"פִּסְחָא","r":"KRU15697","alt":[],"source":"krupnik","glosses":[{"text":"Passover","label":""}],"html":"<p>חג הפסח Passover  ירוש׳ שבת פ״ה י״א ע״א: ארבעתי כסוי דלילי פסחא.</p>","notation":["ז׳"]},"44491":{"h":"פָּסָּטוֹן","r":"KRU15701","alt":[],"source":"krupnik","glosses":[{"text":"ditch","label":""}],"html":"<p>בור ditch  ב״ר פמ״ו: בשעה שיצא למלחמה עשו לו סיעה של פסטון וכו׳.</p>","notation":["ז׳"]},"44492":{"h":"פִּסְטִלּוֹס","r":"KRU15702","alt":[],"source":"krupnik","glosses":[{"text":"pestle","label":""}],"html":"<p>עֱלי pestle  ילק׳ שמואל ק״ב: כהדין פסטילוס.</p>","notation":["ז׳"]},"44493":{"h":"פִּסְטְמָא","r":"KRU15703","alt":[],"source":"krupnik","glosses":[{"text":"credentials","label":""}],"html":"<p>אישור וקיום credentials  ויק״ר פ״ט: פסטמא דילך טבא ולית את דחיל מיניה.</p>","notation":["נ׳"]},"44494":{"h":"פְּסֵי","r":"KRU15704","alt":[],"source":"krupnik","glosses":[{"text":"to step","label":""}],"html":"<p>פסע וצעד to step  ב״מ פ״ו ע״ב: דלא מציא פסיא קניא.</p>","notation":["פ״ע"]},"44495":{"h":"פְּסִיגָא","r":"KRU15705","alt":["פְּסִיגָה"],"source":"krupnik","glosses":[{"text":"branch","label":""}],"html":"<p>ענף branch  עוק׳ פ״א מ״ה: פסיגה של אשכול (ובירוש׳ שם: פסיגא).</p>","notation":[]},"44496":{"h":"פְּסֵידָא","r":"KRU15706","alt":[],"source":"krupnik","glosses":[{"text":"loss","label":""}],"html":"<p>הפסד loss  ב״מ ג׳ ע״א: מאי פסידא אית ליה דלודי.</p>","notation":["ז׳"]},"44497":{"h":"פִּסְיוֹן","r":"KRU15707","alt":[],"source":"krupnik","glosses":[{"text":"pheasant","label":""}],"html":"<p>מין עוף pheasant  במ״ר פ״ז: מי שהיה מתאוה תרנגול או פסיון.</p>","notation":["ז׳"]},"44498":{"h":"פְּסִיחָה","r":"KRU15710","alt":[],"source":"krupnik","glosses":[{"text":"stepping over","label":""}],"html":"<p>דילוג stepping over  ילק׳ שמ׳ ו׳: ופסחתי עליכם אין פסיחה אלא וכו׳.</p>","notation":["נ׳"]},"44499":{"h":"פְּסִילָה","r":"KRU15713","alt":[],"source":"krupnik","glosses":[{"text":"chisel","label":""}],"html":"<p>מפסולת, כלי לפסילה chisel  ירוש׳ קיד׳ פ״א נ״ט ע״ד: מרצע – זה הפסילה.</p>","notation":["נ׳"]},"44500":{"h":"פְּסִילוֹס","r":"KRU15714","alt":["פְּסִילוֹסָא"],"source":"krupnik","glosses":[{"text":"stammerer","label":""}],"html":"<p>כבד פה stammerer  ויק״ר פ״י: והיו קורין אותו פסילוס; ריש קהל״ר: קטוע לישנא פסילוסא.</p>","notation":[]},"44501":{"h":"פְּסִילְיָיה","r":"KRU15715","alt":[],"source":"krupnik","glosses":[{"text":"a species of beans","label":""}],"html":"<p>מין פולים a species of beans  ירוש׳ ביצה פ״א ס׳ ע״ד: תורמוסין ופסילייה.</p>","notation":["נ׳"]},"44502":{"h":"פְּסִינְתָּטוֹן","r":"KRU15716","alt":[],"source":"krupnik","glosses":[{"text":"worm-wood-wine, absinthiatum","label":""}],"html":"<p>יין־לענה worm-wood-wine, absinthiatum  ירוש׳ ע״ז פ״ב מ״א ע״א: החד קונדיטון המר פסינתטון והמתוק מהו.</p>","notation":["ז׳"]},"44503":{"h":"פְּסִיסָא","r":"KRU15718","alt":[],"source":"krupnik","glosses":[{"text":"a man’s name","label":""}],"html":"<p>a man’s name  סנה׳ צ״א ע״א: גביהא בן פסיסא. </p>","notation":["שם איש"]},"44504":{"h":"פְּסִיסִית","r":"KRU15719","alt":["פְּסִיסְפָּס"],"source":"krupnik","glosses":[{"text":"partition","label":""}],"html":"<p>גדר, מחיצה partition  ירוש׳ עיר׳ פ״ט כ״ה ע״ג: הרי שהיתה החצר חלוקה בפסיסיות; נדר׳ פ״ה ל״ט ע״א: חלוקה בפסיספס.</p>","notation":["נ׳"]},"44505":{"h":"פְּסִיעָה","r":"KRU15720","alt":[],"source":"krupnik","glosses":[{"text":"step","label":""}],"html":"<p>צעד step  יומא נ״ג ע״ב: המתפלל צריך שיפסיע שלש פסיעות לאחוריו.</p>","notation":["נ׳"]},"44506":{"h":"פְּסֵיפָס","r":"KRU15721","alt":[],"source":"krupnik","glosses":[{"text":"polished stone","label":"1"},{"text":"mosaic","label":"2"},{"text":"cube, dice","label":"3"}],"html":"<p>1 אבן גזית polished stone  שמו״ר פ״י: בשיש ובפסיפס.\n2 מעשה תשבץ mosaic  תוס׳ נגע׳ ה׳ י׳: קיטא שיש בה פסיפסין צבועין ולבנים.\n3 אבן למשחק, קוביא וכדומה cube, dice  ירוש׳ ר״ה פ״א נ״ז ע״ג: דמשחק בקוביא – זה המשחק בפסיפסין.\n4 עי׳ פִּשְׁפָּשׁ. תוס׳ זבח׳ ז׳ א׳: שני פסיפסין היו בבית החליפות פתוחות למערב.</p>","notation":["ז׳"]},"44507":{"h":"פְסִיקָא","r":"KRU15722","alt":[],"source":"krupnik","glosses":[{"text":"part","label":"1"},{"text":"collection","label":"2"}],"html":"<p>1 חלק part  ב״ב ס״ג ע״א: מצר ארעא דמינה פסיקא.\n2 מגבית collection  ויק״ר פל״ב: אנן עבדין לך פסיקא.\n3 עי׳ פְּסוּקָא. ירוש׳ מו״ק פ״ג פ״ג ע״ב: שתים שלש דלתות – תלת ארבע פסיקן.</p>","notation":["ז׳"]},"44508":{"h":"פְּסִיקָה","r":"KRU15723","alt":[],"source":"krupnik","glosses":[{"text":"cutting apart","label":"1"},{"text":"separated thread","label":"2"}],"html":"<p>1 חיתוך cutting apart  סוכה י״א ע״א: פסיקתן זו היא עשייתן.\n2 חוט נפרד separated thread  נגע׳ פי״א מ״ח: אפילו פסיקה אחת וקשרה.</p>","notation":["נ׳"]},"44509":{"h":"פְּסִיקָה²","r":"KRU15724","alt":[],"source":"krupnik","glosses":[{"text":"pool","label":""}],"html":"<p>בריכה pool  מו״ק ד׳ ע״א: הפסיקות והבריכות שנתמלאו מים.</p>","notation":["נ׳"]},"44510":{"h":"פְּסִיקְיָא","r":"KRU15725","alt":[],"source":"krupnik","glosses":[{"text":"girdle","label":""}],"html":"<p>חגורה girdle  ירוש׳ סנה׳ פ״י כ״ח ע״ד: נתן את הברזל תחת פסיקיא שלו.</p>","notation":["נ׳"]},"44511":{"h":"פְּסִיקְתָּא","r":"KRU15727","alt":[],"source":"krupnik","glosses":[{"text":"agreement","label":""}],"html":"<p>הסכם agreement  מו״ק י״ח ע״ב: שטרי פסיקתא.</p>","notation":["נ׳"]}};
